QUESTIONS.push(
{"id": "DL2-001", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-acetylcholine-nic", "tags": ["drug-list"], "source": "both", "stem": "Acetylcholine acts at the neuromuscular junction as which of the following?", "options": [{"t": "A depolarizing direct agonist", "correct": true, "why": "Acetylcholine opens the muscle nicotinic (Nm) channel and depolarizes the end plate; it is listed with succinylcholine as a depolarizing agent."}, {"t": "A non-depolarizing competitive antagonist", "correct": false, "why": "That is the curare-like drugs (rocuronium, vecuronium, pancuronium), which stop the channel from opening."}, {"t": "An indirect antagonist of acetylcholinesterase", "correct": false, "why": "That is neostigmine, pyridostigmine and the other cholinesterase inhibitors; they raise acetylcholine rather than being it."}, {"t": "An inhibitor of acetylcholine release", "correct": false, "why": "That is botulinum toxin, which acts on the presynaptic terminal."}, {"t": "A partial agonist at α4β2 receptors", "correct": false, "why": "That is varenicline, at the neuronal nicotinic (Nn) receptor in the brain."}], "teach": "The neuromuscular junction drugs split into direct and indirect. Direct drugs bind the muscle nicotinic (Nm) receptor: depolarizing agents are agonists (acetylcholine and succinylcholine); non-depolarizing agents are competitive antagonists (curare-like drugs). Indirect drugs block acetylcholinesterase and raise synaptic acetylcholine.", "quote": "Now, this group is gonna be divided in two different categories, depolarizing, which is the same thing as an agonist, it is activating the receptors, and non-depolarizing, which is gonna be the antagonist. … Acetylcholine is an agonist, but it's broken down very quickly.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 12; transcript 10/5"},
{"id": "DL2-002", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-varenicline", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of varenicline?", "options": [{"t": "Partial agonist at α4β2 neuronal nicotinic (Nn) receptors", "correct": true, "why": "Varenicline is a selective partial agonist at the central α4β2 Nn receptor, with high affinity."}, {"t": "Full agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "A full agonist at Nm that depolarizes the end plate is succinylcholine (and acetylcholine)."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like (non-depolarizing) drugs, which block Nm at skeletal muscle and paralyze; varenicline partly activates brain Nn."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, neostigmine and the other cholinesterase inhibitors (indirect); varenicline binds the receptor itself."}], "teach": "Varenicline binds the α4β2 neuronal nicotinic (Nn) receptor in the central nervous system with high affinity and activates it only partially. That decreases craving and withdrawal and blunts the effect of nicotine, so it is used for smoking cessation.", "quote": "So what is the mechanism of action for Chantix? So it's a partial agonist to what? The alpha 4, beta 2, nicotinic, what type of nicotinic receptor? And for what neuronal.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7–8; transcript 10/5", "dupOf": "PE2-087"},
{"id": "DL2-003", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-varenicline", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the site of action of varenicline?", "options": [{"t": "Neuronal nicotinic (Nn) receptors in the brain", "correct": true, "why": "Neuronal means the brain: varenicline acts on α4β2 Nn receptors in the central nervous system."}, {"t": "Muscle nicotinic (Nm) receptors at the neuromuscular junction", "correct": false, "why": "That is the site of succinylcholine and the curare-like drugs; varenicline is selective for brain α4β2 Nn and leaves Nm alone."}, {"t": "M3 receptors in the ciliary muscle of the eye", "correct": false, "why": "That is where echothiophate’s extra acetylcholine acts; varenicline is nicotinic, not muscarinic."}, {"t": "The presynaptic terminal of motor neurons", "correct": false, "why": "That is the site of botulinum toxin, which prevents acetylcholine release."}], "teach": "Varenicline’s site of action is the central nervous system. Its receptor there is the α4β2 neuronal nicotinic (Nn) receptor; the muscle nicotinic (Nm) receptor at the neuromuscular junction is a different receptor.", "quote": "If it's neuronal, that should be a key that the site of action that drugs where in the brain.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 8; transcript 10/5"},
{"id": "DL2-004", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-varenicline", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Varenicline is most likely to cause which of the following? Select all that apply.", "options": [{"t": "Nausea and vomiting", "correct": true, "why": "Listed as the most common GI side effect (nausea 16–40%)."}, {"t": "Headache", "correct": true, "why": "Its site of action is the brain (α4β2 Nn), so central effects such as headache occur."}, {"t": "Insomnia", "correct": true, "why": "It activates brain Nn receptors (partial agonist), so patients may be unable to sleep."}, {"t": "Depression", "correct": true, "why": "Listed under central nervous system side effects; the site of action is the brain."}, {"t": "Flatulence", "correct": true, "why": "A gastrointestinal complaint: patients “get a lot of gas”."}, {"t": "Hyperkalemia", "correct": false, "why": "Hyperkalemia is a succinylcholine adverse reaction (muscle cells lose K+)."}, {"t": "Histamine release with hypotension", "correct": false, "why": "That is a curare-like drug adverse reaction (most with atracurium)."}], "teach": "Varenicline acts in the brain, so its side effects include central nervous system effects (headache, insomnia, depression); it is a partial agonist, so it still activates the receptor somewhat. Its gastrointestinal side effects are nausea and vomiting (most common) and flatulence. The drug list also warns of mood and behavioral changes.", "quote": "As such, some of the side effects are gonna be where in the brain, depression, lack of being able to sleep because you are activating the receptors … Uh, there's also some GI side effects. Uh, I don't think if I listed for you guys, but flatulence is a complaint for the patients. They get a lot of gas.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 9; transcript 10/5", "note": "The drug list gives headache, insomnia, suicidal thoughts, depression and flatulence and does not list nausea; the slide lists nausea and vomiting as the most common and does not list suicidal thoughts or flatulence. On 10/5 he added flatulence (“I don’t think if I listed for you guys, but flatulence is a complaint”), so flatulence is keyed with the slide’s effects; suicidal thoughts are not asked."},
{"id": "DL2-005", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-succinylcholine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of succinylcholine?", "options": [{"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Succinylcholine opens the nicotinic channel and depolarizes the motor end plate: a depolarizing agent."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the non-depolarizing (curare-like) drugs, which keep the channel shut; succinylcholine opens it."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline, in the brain; succinylcholine acts on Nm at the neuromuscular junction."}, {"t": "Organophosphate inhibitor of acetylcholinesterase", "correct": false, "why": "That is echothiophate, which acts on the enzyme; succinylcholine binds the Nm receptor directly."}], "teach": "Succinylcholine resembles two acetylcholine molecules joined at the alkyl ends. It is an agonist: it opens the nicotinic channel at the neuromuscular junction, but it is not metabolized effectively at the synapse, so the end plate stays depolarized and the muscle is paralyzed.", "quote": "You must know that a sucycholine is an agonist that depolarize or open those ion channels. That's the mechanism of action.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19–20; transcript 10/5"},
{"id": "DL2-006", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "phase-succinylcholine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about succinylcholine’s Phase I and Phase II block is CORRECT?", "options": [{"t": "Phase I keeps the end plate depolarized; Phase II blocks the channel", "correct": true, "why": "Phase I: prolonged depolarization (no repolarization). Phase II: channel blockade prevents movement of Na+/K+ and prolongs the paralysis."}, {"t": "Phase I blocks the channel; Phase II keeps the end plate depolarized", "correct": false, "why": "Reversed: succinylcholine first opens every channel and holds the end plate depolarized; the channel block comes later, with prolonged exposure."}, {"t": "Both phases are competitive block at the acetylcholine binding site", "correct": false, "why": "Competitive block at the binding site is how curare-like drugs act; succinylcholine is an agonist."}, {"t": "Phase II is produced by inhibition of acetylcholinesterase", "correct": false, "why": "Cholinesterase inhibition is the indirect mechanism of drugs such as neostigmine."}], "teach": "In Phase I succinylcholine opens the channel and, because it is not metabolized effectively at the synapse, keeps the motor end plate depolarized; contraction needs end-plate repolarization (“repriming”), so the muscle is paralyzed. In Phase II the channel is blocked, which prevents movement of Na+ and K+ and prolongs the paralysis.", "quote": "And the first one is that opening of all the receptors. That's called phase one. And then if it stays around longer, now it actually can get lodged inside of that channel. And that will be a phase 2. Now it's blocking anything from going through.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 24; transcript 10/5"},
{"id": "DL2-007", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-succinylcholine", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Succinylcholine is most likely to cause which of the following adverse drug reactions? Select all that apply.", "options": [{"t": "Hyperkalemia", "correct": true, "why": "With every Nm channel held open, the muscle cells lose K+ (and gain Ca++ and Na+), so plasma K+ rises."}, {"t": "Hypertension and arrhythmias", "correct": true, "why": "At higher or prolonged doses it opens ganglionic Nn receptors, driving both divisions: hypertension, and arrhythmias as both divisions act on the heart at once."}, {"t": "Post-operative muscle pain (myalgia)", "correct": true, "why": "Caused by unsynchronized contractions."}, {"t": "Hyperthermia", "correct": true, "why": "The muscle fibers keep contracting out of sync, and the patient gets too hot."}, {"t": "Histamine release with marked hypotension", "correct": false, "why": "That is a curare-like drug reaction (atracurium most)."}, {"t": "Miosis and lacrimation", "correct": false, "why": "Those come from extra acetylcholine at eye M3 (echothiophate); succinylcholine acts on nicotinic receptors."}, {"t": "Insomnia and depression", "correct": false, "why": "Those are varenicline reactions, from its action on brain α4β2 Nn; succinylcholine acts at the neuromuscular junction and ganglia."}], "teach": "Succinylcholine’s adverse reactions are hyperkalemia (muscle cells lose K+), hypertension and arrhythmias, post-operative muscle pain and hyperthermia from unsynchronized contractions. It is avoided in renal-deficient and dehydrated patients.", "quote": "so they may get hyperkalemia … So patients can get actually hyperthermia. They get too hot, right, because they can't, their muscles. … so your blood pressure is gonna go up, hypertension, and your heart is gonna be fighting between the parasympathetic and the sympathetic … And patients actually complain of uh muscle pain, myalgia", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 25; transcript 10/5"},
{"id": "DL2-008", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-succinylcholine", "tags": ["drug-list"], "source": "both", "stem": "Besides the muscle nicotinic (Nm) receptor at the neuromuscular junction, at increased doses succinylcholine can also stimulate which site?", "options": [{"t": "Autonomic ganglia, and thus the PNS and SNS", "correct": true, "why": "At increased doses succinylcholine stimulates ganglia, and thus the parasympathetic (PNS) and sympathetic (SNS) nervous systems."}, {"t": "Muscarinic M3 receptors in the bladder", "correct": false, "why": "M3 in the bladder is the site of the overactive-bladder antagonists (oxybutynin and others)."}, {"t": "The presynaptic terminal, blocking acetylcholine release", "correct": false, "why": "Blocking release at the presynaptic terminal is botulinum toxin."}, {"t": "α4β2 receptors in the brain", "correct": false, "why": "That is varenicline’s site; the extra site succinylcholine reaches is the Nn receptor of the autonomic ganglia."}], "teach": "Succinylcholine’s main site is the muscle nicotinic (Nm) receptor at the neuromuscular junction. At increased doses it also stimulates the autonomic ganglia, where neuronal nicotinic (Nn) receptors activate the postganglionic neurons of the parasympathetic nervous system (PNS) and sympathetic nervous system (SNS).", "quote": "So if you infuse for a longer period of time, you're gonna start to open those nicotinic receptors in the ganglia, which is gonna increase your parasympathetic and sympathetic at the same time.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 20; transcript 10/5"},
{"id": "DL2-009", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "ddi-succinylcholine", "tags": ["drug-list"], "source": "both", "stem": "A patient receives succinylcholine together with an inhaled anesthetic such as halothane. Which reaction is this combination associated with?", "options": [{"t": "Malignant hyperthermia", "correct": true, "why": "Listed as the succinylcholine drug–drug interaction with inhaled anesthetics: abnormal Ca++ release from skeletal-muscle stores and muscle heat production."}, {"t": "Histamine release and bronchial spasm", "correct": false, "why": "Histamine release is a curare-like drug reaction (atracurium)."}, {"t": "Hypertensive crisis from dietary tyramine", "correct": false, "why": "That is phenelzine (a monoamine oxidase inhibitor) with tyramine; it involves norepinephrine, not skeletal-muscle Ca++."}, {"t": "Rebound nasal congestion", "correct": false, "why": "That is overuse of phenylephrine, an α1 agonist in the nose; it has nothing to do with skeletal muscle."}], "teach": "With inhaled anesthetics, succinylcholine is associated with malignant hyperthermia: abnormal release of Ca++ from stores in skeletal muscle and heat production by skeletal muscle. Dantrolene is an antagonist at the ryanodine receptor and lowers intracellular Ca++.", "quote": "Uh, this is what I was telling you about that malignant hyperthermia. Their, their body pressure gets really, really high, uh, especially if you combine with an anesthetic that put them to sleep, such as halotane.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 26; transcript 10/5", "note": "The drug list places hyperthermia among succinylcholine’s adverse reactions; the slide places malignant hyperthermia under drug–drug interactions with inhaled anesthetics. On 10/5 he gave both: hyperthermia as an adverse reaction (unsynchronized contraction) and malignant hyperthermia when it is combined with an anesthetic such as halothane. This item keys the interaction.", "level": 2, "ladder": "succinylcholine", "ladderName": "Succinylcholine, halothane and dantrolene"},
{"id": "DL2-010", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-curare", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of rocuronium?", "options": [{"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Rocuronium is a curare-like, non-depolarizing agent: it binds the acetylcholine site and stops the channel from opening."}, {"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is succinylcholine, which opens the channel; rocuronium (a “cur” drug) keeps it shut."}, {"t": "Inhibitor of acetylcholinesterase at the neuromuscular junction", "correct": false, "why": "That is neostigmine and pyridostigmine, which reverse curare-like drugs."}, {"t": "Cleavage of SNARE proteins in the presynaptic terminal", "correct": false, "why": "That is botulinum toxin, which stops acetylcholine release before the receptor; rocuronium acts at the receptor."}], "teach": "The curare-like (non-depolarizing) drugs — tubocurarine (prototype), mivacurium, vecuronium, rocuronium, pancuronium — are direct competitive antagonists. They bind the acetylcholine binding site on the muscle nicotinic (Nm) receptor without opening it; acetylcholine is needed for muscle contraction, so the muscle is paralyzed.", "quote": "But for our purpose on exam two, all I need you to know is that any karate-like drug is what? A competitive, reversible NM antagonist, and by blocking the NM, what are you gonna get? Paralysis, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19, 27; transcript 10/5"},
{"id": "DL2-011", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-nondepolarizing", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs are non-depolarizing neuromuscular blocking agents? Select all that apply.", "options": [{"t": "Vecuronium", "correct": true, "why": "“cur” in the name: a curare-like, competitive Nm antagonist that keeps the channel from opening."}, {"t": "Rocuronium", "correct": true, "why": "“cur” in the name: a curare-like, competitive, reversible Nm antagonist."}, {"t": "Pancuronium", "correct": true, "why": "“cur” in the name: a curare-like, competitive Nm antagonist (tachycardia is its own side effect)."}, {"t": "Mivacurium", "correct": true, "why": "“cur” in the name: a curare-like, competitive Nm antagonist."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is the depolarizing agent (an agonist)."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine is a cholinesterase inhibitor; it reverses curare-like drugs."}, {"t": "Varenicline", "correct": false, "why": "Varenicline is a partial agonist at α4β2 neuronal nicotinic (Nn) receptors in the brain; it does not paralyze."}], "teach": "Both drug types cause paralysis. Depolarizing: succinylcholine (agonist, opens nicotinic channels). Non-depolarizing: curare (prototype), mivacurium, vecuronium, rocuronium and pancuronium (competitive antagonists, stop the nicotinic channels from opening). A drug with “cur” in the middle of its name is curare-like: a competitive, reversible muscle nicotinic (Nm) antagonist.", "quote": "However, if you know that it is a C U R in the middle, it doesn't matter if it's vecuronio, Rocuronio, Pencuronio. They're all the same.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19; transcript 10/5"},
{"id": "DL2-012", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-curare", "tags": ["drug-list"], "source": "both", "stem": "A patient is administered rocuronium. Which of the following is most likely to occur?", "options": [{"t": "Paralysis", "correct": true, "why": "Rocuronium blocks the muscle nicotinic (Nm) receptor, so paralysis occurs every time; it is what the drug is used for."}, {"t": "Diarrhea", "correct": false, "why": "Gut motility is driven through muscarinic receptors; rocuronium blocks only the muscle nicotinic (Nm) receptor."}, {"t": "Vasoconstriction", "correct": false, "why": "Blood vessels respond through adrenergic (sympathetic) receptors; rocuronium blocks the muscle nicotinic (Nm) receptor."}, {"t": "Sedation", "correct": false, "why": "Curare-like drugs do not cross the blood–brain barrier and do not put the patient to sleep."}], "teach": "Rocuronium is a curare-like drug: a competitive, reversible muscle nicotinic (Nm) antagonist, so paralysis always occurs. The other adverse reactions depend on the drug: paralysis of the diaphragm (respiratory paralysis), tachycardia more often with pancuronium, and massive histamine release with atracurium. They have no central nervous system (CNS) effect.", "quote": "If a patient is administered Rocuronium. Which of the following is most likely to occur? … So what we have over here is paralysis. That's always going to happen.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 27, 30, 32; transcript 10/5", "note": "The drug list gives histamine release, hypotension and tachycardia and omits respiratory paralysis; the slide lists respiratory paralysis first, ties tachycardia to pancuronium and histamine release mainly to atracurium (not on the list). On 10/5 he called these drug-dependent and said that for Exam 2 he needs only that any curare-like drug is a competitive, reversible Nm antagonist that causes paralysis, so this item keys paralysis (his in-class question on rocuronium).", "level": 1},
{"id": "DL2-013", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "cns-curare", "tags": ["drug-list"], "source": "both", "stem": "Which statement about the curare-like drugs (for example vecuronium) is CORRECT?", "options": [{"t": "They have no central nervous system effect", "correct": true, "why": "They do not cross the blood–brain barrier: no effect on memory or sleep; they only paralyze."}, {"t": "They cross the blood–brain barrier and cause sedation", "correct": false, "why": "They stay out of the brain, so they paralyze without sedating; an anesthetic is given for sleep."}, {"t": "They are agonists that keep the end plate depolarized", "correct": false, "why": "That is succinylcholine, the depolarizing agonist; the curare-like drugs keep the channel shut."}, {"t": "They raise acetylcholine levels at the synapse", "correct": false, "why": "Raising acetylcholine is what the cholinesterase inhibitors do, and it reverses the curare-like drugs."}], "teach": "The curare-like drugs act only at the neuromuscular junction, where they block the muscle nicotinic (Nm) receptor competitively. They have no central nervous system effect, so a paralyzed patient is not sedated by them; they are used as an adjuvant in surgical anesthesia, not as an anesthetic.", "quote": "The key thing for you to remember is these drugs don't cross the blood brain barrier. They have no effect on memory or putting your patient to sleep. They just paralyze your patients.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 27, 32; transcript 10/5"},
{"id": "DL2-014", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about physostigmine is CORRECT?", "options": [{"t": "It crosses the blood–brain barrier", "correct": true, "why": "Physostigmine is a tertiary amine and readily penetrates the central nervous system."}, {"t": "It is a quaternary amine that stays out of the brain", "correct": false, "why": "That describes pyridostigmine and neostigmine: quaternary amines stay out of the brain, while physostigmine, a tertiary amine, gets in."}, {"t": "It irreversibly phosphorylates acetylcholinesterase", "correct": false, "why": "That is the organophosphates (echothiophate, parathion, sarin)."}, {"t": "It is a muscarinic receptor antagonist", "correct": false, "why": "Physostigmine inhibits acetylcholinesterase; atropine is the muscarinic antagonist."}], "teach": "Physostigmine is a reversible acetylcholinesterase inhibitor with a longer duration of action. As a tertiary amine it readily penetrates the central nervous system, so it acts in the brain and the periphery, and it is the drug of choice for poisoning by anti-muscarinic agents such as atropine.", "quote": "So one over here, they're both reversible, right, but physostigamine, it crosses the brain, the blood vein barrier, penetrates the blood vein barrier, as neostigimine or pyredos stigmine do not cross the blood vein barrier.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5"},
{"id": "DL2-015", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine-use", "tags": ["drug-list", "use"], "source": "both", "stem": "A patient is poisoned with atropine. Which cholinesterase inhibitor is the drug of choice?", "options": [{"t": "Physostigmine", "correct": true, "why": "Drug of choice for poisoning by anti-muscarinic agents such as atropine; it reaches the central nervous system."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine does not cross the blood–brain barrier; its uses are myasthenia gravis and curare reversal."}, {"t": "Pyridostigmine", "correct": false, "why": "Pyridostigmine does not cross the blood–brain barrier; it stays in the periphery."}, {"t": "Echothiophate", "correct": false, "why": "Echothiophate is an organophosphate used in the eye for glaucoma."}], "teach": "Atropine blocks muscarinic receptors in the brain and periphery. Physostigmine raises acetylcholine by inhibiting acetylcholinesterase and, as a tertiary amine, reaches the central nervous system too, so it is the drug of choice for anti-muscarinic poisoning.", "quote": "So, uh, Pfizostigamine typically is gonna be used for as an antidote if somebody has this, uh, you know, overdose on, say, atropine", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5", "level": 3, "ladder": "atropine-poisoning", "ladderName": "Atropine poisoning and physostigmine"},
{"id": "DL2-016", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "bbb-ache", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which acetylcholinesterase inhibitors cross the blood–brain barrier? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "Tertiary amine; readily penetrates the central nervous system."}, {"t": "Donepezil", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Rivastigmine", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Neostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}, {"t": "Pyridostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}], "teach": "Physostigmine (tertiary amine) and the Alzheimer’s drugs donepezil and rivastigmine (very lipid soluble) cross the blood–brain barrier. Pyridostigmine and neostigmine are quaternary amines and do not, so they act at the neuromuscular junction without central effects.", "quote": "physostigamine, it crosses the brain, the blood vein barrier, penetrates the blood vein barrier, as neostigimine or pyredos stigmine do not cross the blood vein barrier. … For our exam purpose, I only need you to know rivastigamine and donepezil … And those drugs are extremely lipid soluble. They will get to the brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39–40; transcript 10/5"},
{"id": "DL2-017", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "neostigmine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about neostigmine and pyridostigmine is CORRECT?", "options": [{"t": "They do not cross the blood–brain barrier", "correct": true, "why": "They are quaternary amines and do NOT cross the blood–brain barrier, so their site of action is the neuromuscular junction."}, {"t": "They are the drugs of choice for atropine poisoning", "correct": false, "why": "That is physostigmine, which reaches the brain."}, {"t": "They are used for early Alzheimer’s disease", "correct": false, "why": "That is donepezil and rivastigmine, which cross the blood–brain barrier."}, {"t": "They block the muscle nicotinic receptor directly", "correct": false, "why": "They inhibit acetylcholinesterase (indirect); direct block of Nm is the curare-like drugs."}], "teach": "Pyridostigmine and neostigmine are reversible acetylcholinesterase inhibitors with a longer duration of action. They are quaternary amines that do not cross the blood–brain barrier, so they act at the neuromuscular junction: they treat myasthenia gravis and reverse curare-like overdose.", "quote": "as neostigimine or pyredos stigmine do not cross the blood vein barrier. … But for myasthenia gravis patients, let's keep the one that stays in the periphery", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5"},
{"id": "DL2-018", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "reverse-curare-neostigmine", "tags": ["drug-list", "use"], "source": "both", "stem": "A patient remains paralyzed after a curare-like drug. Which drug reverses the block by raising acetylcholine at the neuromuscular junction?", "options": [{"t": "Neostigmine", "correct": true, "why": "A cholinesterase inhibitor used to reverse curare-like overdose; more acetylcholine competes the curare-like drug off the receptor."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is itself a paralyzing (depolarizing) drug; adding it deepens the paralysis."}, {"t": "Atropine", "correct": false, "why": "Atropine blocks muscarinic receptors; it does not raise acetylcholine."}, {"t": "Botulinum toxin", "correct": false, "why": "Botulinum toxin lowers acetylcholine release and relaxes muscle."}], "teach": "Curare-like drugs are competitive antagonists, so their block can be overcome by more acetylcholine. Neostigmine and pyridostigmine inhibit acetylcholinesterase, raise synaptic acetylcholine at the neuromuscular junction and reverse the block.", "quote": "So neo stigamine, which does not cross the blood brain barrier but can increase the levels of acetylcholine in the synapse of your skeletal muscle, would give you a better chance of outcompeting karate and regain some movement for your friend. Yes. I have a question similar to this in the exam every year, and about 30% of the class misses it.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 33, 39; transcript 10/5", "level": 3},
{"id": "DL2-020", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-ache", "tags": ["drug-list"], "source": "both", "stem": "Donepezil is most likely to cause which of the following?", "options": [{"t": "Diarrhea and salivation", "correct": true, "why": "Cholinesterase inhibitor adverse reactions are DUMBBELSS (diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation) from excess acetylcholine."}, {"t": "Dry mouth and constipation", "correct": false, "why": "Those are anti-DUMBBELSS effects of muscarinic antagonists."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is an anti-DUMBBELSS effect; excess acetylcholine causes miosis."}, {"t": "Tachycardia and bronchial dilation", "correct": false, "why": "Those are atropine effects; excess acetylcholine causes bradycardia and bronchial constriction."}], "teach": "Cholinesterase inhibitors raise synaptic acetylcholine, so their adverse reactions are the symptoms of excess acetylcholine: DUMBBELSS — diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation. Central effects include insomnia, agitation and dizziness.", "quote": "So what kind of side effects do you expect this drug to produce? Dumbbells across the border, right? … So diarrhea, urination, meiosis, bronchial constriction, bradycardia, emesis, which is the same thing as vomiting, lachrymation, salivation, and stimulation of the brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 41; transcript 10/5", "level": 1},
{"id": "DL2-021", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-echothiophate", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of echothiophate?", "options": [{"t": "Irreversible inhibitor of acetylcholinesterase", "correct": true, "why": "Echothiophate is an organophosphate inhibitor of acetylcholinesterase; organophosphates bind the enzyme covalently (irreversible)."}, {"t": "Reversible inhibitor of acetylcholinesterase in the brain", "correct": false, "why": "That is donepezil and rivastigmine; organophosphates bind the enzyme covalently."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is pilocarpine and carbachol, which act at the receptor directly."}, {"t": "Muscarinic antagonist in the eye", "correct": false, "why": "That is tropicamide, which blocks M3 and dilates the pupil; echothiophate raises acetylcholine and constricts it."}], "teach": "Echothiophate is an organophosphate: it inhibits acetylcholinesterase and raises acetylcholine, which increases M3 activation in the ciliary muscle and lowers intraocular pressure by increasing aqueous humor outflow (glaucoma). Organophosphates form a stable covalent bond with the enzyme, so the inhibition is irreversible.", "quote": "So what we can do is we can get echothiofate. … Those are irreversible antagonists to the acetylchonasterase enzyme.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 42, 45; transcript 10/5", "note": "The drug list does not say whether echothiophate is reversible; the slides call organophosphates irreversible, and on 10/5 he called echothiophate an irreversible acetylcholinesterase antagonist. Keyed so."},
{"id": "DL2-022", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-adr-echothiophate", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Echothiophate acts on M3 receptors in the ciliary muscle of the eye. It is most likely to cause which of the following? Select all that apply.", "options": [{"t": "Miosis and blurred vision", "correct": true, "why": "Listed adverse reaction: more M3 activation constricts the pupil."}, {"t": "Lacrimation", "correct": true, "why": "More acetylcholine on lacrimal gland M3: tearing, the L of DUMBBELSS."}, {"t": "Stinging and redness of the eyes", "correct": true, "why": "Local irritation from drops placed in the eye (“anything that you put in the eye is gonna sting”)."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is what tropicamide (an M3 antagonist) produces."}, {"t": "Dry eyes", "correct": false, "why": "Raised acetylcholine increases lacrimation, not dryness."}], "teach": "Echothiophate raises acetylcholine and so increases M3 activation in the ciliary muscle (its site of action). Its listed adverse reactions are miosis and blurred vision, lacrimation, and stinging and redness of the eyes.", "quote": "Uh, as a side effect over here, right, it's gonna cause some of meiosis, blurred vision, because your pupils are gonna get smaller. You can't help that. You can get the the lachrymation. Anything that you put in the eye is gonna sting, it's gonna cause a little bit of uh redness to the eye.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 45; transcript 10/5", "level": 1},
{"id": "DL2-023", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "botox", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of botulinum toxin?", "options": [{"t": "Blocks acetylcholine release by cleaving SNARE", "correct": true, "why": "Botulinum toxin is an endopeptidase; it cleaves sites on SNARE proteins in the presynaptic terminal, so acetylcholine cannot be released."}, {"t": "Competitively blocks muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like drugs, which act on the postsynaptic receptor."}, {"t": "Inhibits acetylcholinesterase in the synaptic cleft", "correct": false, "why": "That is the cholinesterase inhibitors, which raise acetylcholine."}, {"t": "Depolarizes the motor end plate", "correct": false, "why": "That is succinylcholine at the Nm receptor; botulinum toxin acts before the receptor, on release."}], "teach": "Botulinum toxin acts at the presynaptic terminal. Its active fragments are endopeptidases whose substrates are the SNARE proteins needed for vesicle docking and exocytosis; cleaving them blocks acetylcholine release, which relaxes muscle.", "quote": "So Botox is an enzyme that breaks down the snare protein, and if you don't have the snare protein, your vesicles can't bind properly and thus you can't release the cetylcholine.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 46, 50; transcript 10/5", "note": "The drug list colours botulinum toxin red (antagonist); the slides describe it as blocking acetylcholine release, not as a receptor antagonist. Keyed to the slide wording."},
{"id": "DL2-024", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-indirect-ache", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs act as indirect antagonists by inhibiting acetylcholinesterase? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "A “-stigmine”: blocks acetylcholinesterase, so acetylcholine rises (and it reaches the brain)."}, {"t": "Pyridostigmine", "correct": true, "why": "A “-stigmine”: blocks acetylcholinesterase at the neuromuscular junction, so acetylcholine rises."}, {"t": "Neostigmine", "correct": true, "why": "A “-stigmine”: blocks acetylcholinesterase, so acetylcholine rises and can outcompete curare."}, {"t": "Rivastigmine", "correct": true, "why": "A “-stigmine”: blocks acetylcholinesterase in the brain and periphery, so acetylcholine rises."}, {"t": "Succinylcholine", "correct": false, "why": "A direct depolarizing agonist: it binds the Nm receptor itself, not the enzyme."}, {"t": "Varenicline", "correct": false, "why": "A direct partial agonist: it binds the α4β2 Nn receptor itself, not the enzyme."}, {"t": "Botulinum toxin", "correct": false, "why": "Prevents acetylcholine release; it does not inhibit acetylcholinesterase."}], "teach": "Indirect drugs at the neuromuscular junction bind the enzyme that breaks down acetylcholine, not the receptor: acetylcholinesterase antagonists such as physostigmine, pyridostigmine, neostigmine, donepezil, rivastigmine and echothiophate. A drug name ending in “stigmine” marks a cholinesterase inhibitor. Blocking the enzyme raises synaptic acetylcholine.", "quote": "Now, the key for you in the exam is anytime you see a drug that has a stickyine in it, you know it has to do what with the pseudocholinesterase enzyme. … and rivasciamine is an antagonist to the psytocholesterase enzyme.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 10, 12; transcript 10/5"},
{"id": "DL2-025", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-agonist-nmj", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which of the following drugs are direct nicotinic agonists? Select all that apply.", "options": [{"t": "Acetylcholine", "correct": true, "why": "The endogenous agonist: it opens the nicotinic channel (a depolarizing agent at Nm)."}, {"t": "Succinylcholine", "correct": true, "why": "A depolarizing agonist: it opens the Nm channel and holds it open."}, {"t": "Varenicline", "correct": true, "why": "A partial agonist: it activates α4β2 neuronal nicotinic (Nn) receptors in the brain, submaximally."}, {"t": "Rocuronium", "correct": false, "why": "It binds Nm but blocks it (competitive antagonist, non-depolarizing); it does not activate it."}, {"t": "Neostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor: it raises acetylcholine (indirect) but does not bind the receptor itself."}, {"t": "Botulinum toxin", "correct": false, "why": "It prevents acetylcholine release, before the receptor; it lowers, not mimics, acetylcholine."}], "teach": "The nicotinic agonists are acetylcholine, nicotine, varenicline (selective partial agonist at α4β2 Nn) and succinylcholine. Curare-like drugs are direct antagonists; cholinesterase inhibitors are indirect.", "quote": "Pennyline is a partial agonist to the NN receptor. Succylcholine is an agonist to the nicotinic receptor. … Acetylcholine is an agonist, but it's broken down very quickly.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7; transcript 10/5"},
{"id": "DL2-026", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-bethanechol", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of bethanechol?", "options": [{"t": "Non-selective, reversible muscarinic (M1–M3) agonist", "correct": true, "why": "Bethanechol is grouped with acetylcholine, methacholine and carbachol as a non-selective muscarinic agonist."}, {"t": "Non-selective, reversible muscarinic (M1–M3) antagonist", "correct": false, "why": "Blocking M1–M3 is atropine (a “trop” drug); bethanechol, a “chol” drug, activates them."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine and neostigmine, which raise acetylcholine (indirect); bethanechol binds the receptor directly."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline (brain α4β2 Nn); bethanechol acts only on muscarinic receptors."}], "teach": "Acetylcholine, methacholine, carbachol, bethanechol and pilocarpine are non-selective, reversible agonists at the muscarinic receptors (M1, M2, M3); being reversible and competitive, an overdose can be outcompeted by an antagonist. Apart from acetylcholine, they act only at muscarinic receptors, not nicotinic ones.", "quote": "Well, for these drugs, all of them are gonna be non-selective agonists to the M1s, M2s, and M3s. … They're all reversible, so they're all competitive, they're gonna bind, and they're gonna come off.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 11–12; transcript 10/5"},
{"id": "DL2-027", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "group-musc-agonists", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs are non-selective muscarinic agonists? Select all that apply.", "options": [{"t": "Methacholine", "correct": true, "why": "The “chol” marks a cholinergic agonist: it activates M1, M2 and M3."}, {"t": "Carbachol", "correct": true, "why": "The “chol” marks a cholinergic agonist: it activates M1, M2 and M3."}, {"t": "Pilocarpine", "correct": true, "why": "No “chol”, so it is known by name: a non-selective muscarinic agonist (M1–M3) with no effect on nicotinic receptors."}, {"t": "Scopolamine", "correct": false, "why": "A non-selective muscarinic antagonist (it also blocks histamine and serotonin receptors): it blocks rather than activates."}, {"t": "Tiotropium", "correct": false, "why": "A “trop” drug: an inhaled muscarinic antagonist that blocks rather than activates."}, {"t": "Physostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor; it raises acetylcholine but does not bind the receptor."}], "teach": "The direct muscarinic agonists are acetylcholine, methacholine, carbachol, bethanechol and pilocarpine; all are non-selective (M1, M2, M3) and reversible. The “chol” in methacholine, carbachol and bethanechol marks them as cholinergic; pilocarpine has no “chol” and has to be known by name. Physostigmine reaches the same receptors indirectly by raising acetylcholine.", "quote": "So, I have over here methylcholine, carbacol, Bethenacol, so they all have that call for cholinergic, right? … but for our purpose on the exam, I'm gonna expect you to know pilocarpine as one of the two, OK?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2–3; PCOL-Cholinergic-26s.pdf slide 11; transcript 10/5"},
{"id": "DL2-029", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "pilocarpine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about pilocarpine is CORRECT?", "options": [{"t": "It has no effect on nicotinic receptors", "correct": true, "why": "Pilocarpine binds only muscarinic receptors; it does not bind or activate nicotinic receptors."}, {"t": "It binds muscarinic receptors irreversibly", "correct": false, "why": "The muscarinic agonists are all reversible and competitive; they bind and come off."}, {"t": "It is selective for the M2 receptor", "correct": false, "why": "It is a non-selective muscarinic agonist (M1, M2, M3)."}, {"t": "It blocks muscarinic receptors and dries the mouth", "correct": false, "why": "It activates muscarinic receptors; it is used to treat dry mouth."}], "teach": "Pilocarpine is a non-selective, reversible muscarinic agonist (M1, M2, M3). It does not bind or activate nicotinic receptors; among the cholinergic agonists only acetylcholine acts at both nicotinic and muscarinic receptors. At the salivary glands (M3, Gq, ↑Ca++) it causes salivation.", "quote": "What I need you to know is that it does not bind or activate the nicotinic receptors. It only has affinity for the muscarinics.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 14; transcript 10/5"},
{"id": "DL2-030", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-musc-agonist", "tags": ["drug-list"], "source": "both", "stem": "Which of the following would be the least likely effect of bethanechol?", "options": [{"t": "Mydriasis", "correct": true, "why": "Muscarinic agonists cause miosis (M3 in the iris); mydriasis is an antagonist effect."}, {"t": "Diarrhea", "correct": false, "why": "Likely: M3 in the gut increases peristalsis and secretion (the D of DUMBBELSS)."}, {"t": "Bradycardia", "correct": false, "why": "Likely: M2 (Gi) at the SA and AV node lowers heart rate."}, {"t": "Bronchial constriction", "correct": false, "why": "Likely: M3 (Gq) contracts bronchial smooth muscle."}, {"t": "Salivation", "correct": false, "why": "Likely: M3 on the salivary glands increases secretion."}], "teach": "Muscarinic agonists produce DUMBBELSS: diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation of the central nervous system. Bradycardia comes through M2 in the heart (Gi); the rest of the peripheral effects come through M3 (Gq, ↑Ca++).", "quote": "So when we give an agonist, we're gonna produce what the dumbbells, right? We're gonna increase motilage in tone, so diarrhea, cramping, increased urination, uh, meiosis, which makes your pupil small, bradycardia, bronchial constriction, emesis", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 13; transcript 10/5", "level": 1},
{"id": "DL2-031", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-atropine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of atropine?", "options": [{"t": "Non-selective muscarinic (M1–M3) antagonist", "correct": true, "why": "Atropine is a naturally occurring alkaloid that blocks M1, M2 and M3, reversibly."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "Activating M1–M3 is bethanechol, carbachol and the other “chol” agonists; atropine blocks the receptors (anti-DUMBBELSS)."}, {"t": "Selective M1 and M3 muscarinic antagonist", "correct": false, "why": "M1 and M3 is tiotropium’s profile on the slide; atropine blocks M2 as well, which is why it raises heart rate."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, which treats atropine poisoning."}], "teach": "Atropine is a non-selective, reversible muscarinic antagonist (M1, M2, M3), acting in the central nervous system and periphery. Blocking the receptors where acetylcholine produces DUMBBELSS gives the anti-DUMBBELSS picture.", "quote": "So when you see drugs like atropine with a trope, what you should be thinking about, those are non-selective muscarinic antagonists that is going to block the M1s, the M2s, and the M3s everywhere else. … This drug is going to be also reversible as well.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17; transcript 10/5"},
{"id": "DL2-032", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-atropine", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "An overdose of atropine is most likely to cause which of the following? Select all that apply.", "options": [{"t": "Tachycardia", "correct": true, "why": "M2 block in the heart → ↑ heart rate."}, {"t": "Mydriasis", "correct": true, "why": "M3 block in the pupil → mydriasis."}, {"t": "Constipation", "correct": true, "why": "M3 block in the gastrointestinal tract → constipation."}, {"t": "Dry mouth", "correct": true, "why": "M3 block on glands → dry mouth."}, {"t": "Sedation", "correct": true, "why": "M1 block in the brain → sedation; at higher doses, hallucinations (“mad as a hatter”)."}, {"t": "Bronchial constriction", "correct": false, "why": "Atropine causes bronchial dilation; constriction is a muscarinic agonist effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is a muscarinic agonist effect; atropine dilates the pupil."}], "teach": "Atropine overdose gives anti-DUMBBELSS: M2 block in the heart raises heart rate; M3 block causes mydriasis, constipation, dry mouth and bronchial dilation; M1 block in the brain causes sedation. Toxicity is summarized as dry as a bone, hot as a pistol, red as a beet, blind as a bat, mad as a hatter.", "quote": "The anti-dumbbells, if it is for diarrhea, you get constipation. … Meiosis, you get the midriasis. Your pupils dilate, instead of getting the bronchial constriction, you get bronchial dilation. You can't cry. You can't sweat, and you're gonna go sedated.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 19, 32; transcript 10/5", "note": "The drug list gives drowsiness for atropine; the slides give its central effects as hallucinations, restlessness and coma (dose-dependent) and give drowsiness for scopolamine. On 10/5 he listed sedation among atropine’s anti-DUMBBELSS effects (“you’re gonna go sedated”), so sedation is keyed.", "level": 1, "ladder": "atropine-poisoning", "ladderName": "Atropine poisoning and physostigmine"},
{"id": "DL2-033", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-heart", "tags": ["drug-list", "apply"], "source": "both", "stem": "Atropine raises heart rate by blocking which receptor?", "options": [{"t": "M2 in the heart", "correct": true, "why": "M2 (Gi) at the SA and AV node lowers heart rate when acetylcholine binds; blocking it raises heart rate."}, {"t": "M3 in the heart", "correct": false, "why": "M3 mediates smooth muscle, gland, eye and endothelial effects; the cardiac muscarinic receptor is M2."}, {"t": "β1 in the heart", "correct": false, "why": "β1 is the adrenergic receptor that raises heart rate when activated; atropine does not act there."}, {"t": "Neuronal nicotinic (Nn) in ganglia", "correct": false, "why": "Atropine is a muscarinic antagonist, not a nicotinic one."}], "teach": "Acetylcholine slows the heart through M2 (Gi, ↓cAMP) at the SA and AV node. Atropine blocks M2, so the parasympathetic brake is removed and heart rate rises; atropine is used for bradycardia or atrioventricular nodal block.", "quote": "So if I block the M2s, now the sympathetic is unopposed, I'm going to get what? tachycardia.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 10, 19; transcript 10/5", "level": 1},
{"id": "DL2-034", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-organophosphate", "tags": ["drug-list", "use"], "source": "both", "stem": "In organophosphate poisoning, how does atropine help?", "options": [{"t": "It blocks excess acetylcholine at muscarinic sites", "correct": true, "why": "Atropine (M1, M2, M3 antagonist) reduces the effects of acetylcholine at muscarinic sites: anti-DUMBBELSS."}, {"t": "It regenerates the phosphorylated acetylcholinesterase", "correct": false, "why": "Regenerating the enzyme is pralidoxime (2-PAM), the cholinesterase reactivator."}, {"t": "It lowers acetylcholine release from the nerve terminal", "correct": false, "why": "That is botulinum toxin; atropine works after release, at the muscarinic receptor."}, {"t": "It blocks nicotinic receptors at the neuromuscular junction", "correct": false, "why": "Atropine acts at muscarinic, not nicotinic, receptors."}], "teach": "Organophosphates irreversibly inhibit acetylcholinesterase, so acetylcholine builds up and produces severe DUMBBELSS. Atropine blocks M1, M2 and M3 and reduces the effects of acetylcholine at muscarinic sites; pralidoxime (2-PAM) reactivates the enzyme.", "quote": "You wanna give to pm to break some of those bonds, but it can't stop the dumbbells, right? So how can we manage the dumbbells? By giving atropine.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 44; PCOL-Cholinergic-26s.pdf slide 20; transcript 10/5", "level": 3},
{"id": "DL2-035", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-scopolamine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of scopolamine?", "options": [{"t": "Muscarinic, histamine and serotonin antagonist", "correct": true, "why": "Scopolamine is a non-selective, reversible alkaloid antagonist at muscarinic, histamine and serotonin receptors."}, {"t": "Selective antagonist at M3 receptors in the bladder", "correct": false, "why": "That is solifenacin and trospium; scopolamine is very non-selective and acts mainly in the brain."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "That is pilocarpine and the other agonists; scopolamine blocks the receptors, it does not activate them."}, {"t": "Inhibitor of acetylcholinesterase in the brain", "correct": false, "why": "That is donepezil and the other lipophilic cholinesterase inhibitors; scopolamine blocks the receptor, not the enzyme."}], "teach": "Scopolamine, like atropine, is a naturally occurring, non-selective and reversible muscarinic antagonist; it also antagonizes histamine and serotonin receptors. It penetrates the central nervous system more rapidly than atropine and is used for motion sickness.", "quote": "We also have the scopolamine, which is a non-selective muscarin. That one is really non-selective. That not only blocks all the muscarinics, but also histamine and serotonin receptors.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17; transcript 10/5", "note": "The drug list calls scopolamine a non-selective muscarinic antagonist (M1, M2, M3) and does not mention histamine or serotonin receptors; the slide does, and on 10/5 he said the same (“not only blocks all the muscarinics, but also histamine and serotonin receptors”). Keyed to the slide and transcript."},
{"id": "DL2-036", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "scopolamine-cns", "tags": ["drug-list"], "source": "both", "stem": "Which statement about scopolamine is CORRECT?", "options": [{"t": "It causes drowsiness", "correct": true, "why": "Scopolamine acts in the central nervous system (CNS), which it penetrates more rapidly; drowsiness is among its effects, with euphoria and amnesia."}, {"t": "It does not cross into the CNS", "correct": false, "why": "Not crossing the blood–brain barrier describes neostigmine and pyridostigmine."}, {"t": "It causes salivation and diarrhea", "correct": false, "why": "Those are muscarinic agonist (DUMBBELSS) effects; scopolamine causes dry mouth and constipation."}, {"t": "It blocks only the M2 receptor", "correct": false, "why": "Scopolamine is very non-selective: all muscarinic receptors plus histamine and serotonin receptors."}], "teach": "Scopolamine is a muscarinic antagonist whose site of action is mainly the central nervous system (CNS), which it penetrates more rapidly. It causes drowsiness, euphoria and amnesia; it blocks emesis, but the other anti-DUMBBELSS effects (dry mouth, constipation, urinary retention) come with it.", "quote": "Typical typically people use dromamine or scopolamine for motion sickness. … You're drowsy, but you have to take about 3 hours before you get on the boat", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 24; transcript 10/5"},
{"id": "DL2-037", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "benztropine", "tags": ["drug-list"], "source": "both", "stem": "Benztropine is a muscarinic antagonist. Where is its site of action?", "options": [{"t": "The central nervous system", "correct": true, "why": "Benztropine, an atropine analog, blocks M1 in the brain; it is used in Parkinson’s patients for tremor and rigidity."}, {"t": "The lungs, by inhalation", "correct": false, "why": "That is ipratropium, tiotropium, aclidinium and umeclidinium."}, {"t": "M3 receptors in the bladder", "correct": false, "why": "Bladder M3 is the site of oxybutynin, trospium and solifenacin; benztropine favors M1 in the brain."}, {"t": "The eye (pupil)", "correct": false, "why": "The eye is tropicamide’s site (M3 block, mydriasis); benztropine acts in the brain."}], "teach": "In Parkinson’s disease, 70–80% of the dopaminergic neurons from the substantia nigra to the striatum are lost and acetylcholine activity is left unopposed. Benztropine, an analog of atropine, is more selective for M1 receptors in the brain, so it has fewer anti-DUMBBELSS effects elsewhere; it is an add-on to L-dopa for tremor and rigidity.", "quote": "Uh, we can also use an analog of atropine called benztropine. This is a drug used for treatment of Parkinson's disease. … benzotropine is more selective to the beta 1s in the to the M1s in the brain, and it's gonna have less of those anti-dumbbells that you can get, uh, someplace else.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 25; transcript 10/5", "note": "The drug list calls benztropine a non-selective muscarinic antagonist (M1, M2, M3); the slide names the drug and its use without its selectivity. On 10/5 he said benztropine is more selective for M1 in the brain than atropine, with fewer anti-DUMBBELSS effects elsewhere. Only the site of action (central nervous system) is keyed."},
{"id": "DL2-038", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "tropicamide", "tags": ["drug-list", "apply"], "source": "both", "stem": "Tropicamide dilates the pupil. Which mechanism explains this?", "options": [{"t": "It blocks M3, leaving the SNS unopposed", "correct": true, "why": "The parasympathetic system constricts the pupil through M3 (Gq → IP3, Ca++); blocking M3 leaves the sympathetic nervous system (SNS) unopposed → mydriasis."}, {"t": "It activates α1 receptors on the radial muscle", "correct": false, "why": "Activating α1 to cause mydriasis is phenylephrine; tropicamide is a “trop” muscarinic antagonist."}, {"t": "It inhibits acetylcholinesterase in the eye", "correct": false, "why": "Inhibiting acetylcholinesterase in the eye (echothiophate) causes miosis."}, {"t": "It activates M3 receptors in the ciliary muscle", "correct": false, "why": "M3 activation constricts the pupil (miosis)."}], "teach": "The sympathetic nervous system (SNS) dilates the pupil and the parasympathetic nervous system (PNS) constricts it through M3 (Gq → PLC → IP3 and Ca++). Tropicamide blocks M3 in the eye, so the SNS is unopposed and the pupil dilates (mydriasis).", "quote": "Well, we know that the sympathetic cause pupil dilation. The parasympathetic cause pupil constriction. … So by blocking those M3s, I'm gonna get, instead of pupil constriction, I'm gonna get pupil dilation, also known as madriasis.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 26; transcript 10/5", "level": 1},
{"id": "DL2-039", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "ipra-vs-tio", "tags": ["drug-list", "tell"], "source": "both", "stem": "Which statement correctly tells ipratropium and tiotropium apart?", "options": [{"t": "Ipratropium is short acting; tiotropium is long acting", "correct": true, "why": "Ipratropium is the short-acting muscarinic antagonist (SAMA, 3–4 times a day); tiotropium is a long-acting muscarinic antagonist (LAMA, once a day)."}, {"t": "Ipratropium is long acting; tiotropium is short acting", "correct": false, "why": "Reverses the two: ipratropium is the SAMA, tiotropium the LAMA."}, {"t": "Both are agonists at M3 in bronchial smooth muscle", "correct": false, "why": "Both are antagonists; M3 activation constricts the bronchi."}, {"t": "Both reach high levels in the blood after inhaling", "correct": false, "why": "Both were built for very low bioavailability, so they stay mainly in the lungs."}], "teach": "Both are inhaled muscarinic antagonists used in the lungs, where M3 (Gq → IP3, Ca++) constricts bronchial smooth muscle and only the parasympathetic system innervates. Ipratropium is a short-acting muscarinic antagonist (SAMA); tiotropium is a long-acting muscarinic antagonist (LAMA). Both have very low bioavailability and stay mainly in the airways.", "quote": "So we have, for example, ipratropium, that's the short acting called SAA, right? Or the teotropin-like drugs, which are called the lemmas.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 28; transcript 10/5", "note": "The slide gives ipratropium as M1, M2 and M3 and tiotropium as M1 and M3. On 10/5 he called both “less selective” and said either could affect M2 or M3 if it got into the circulation. The receptor profiles are therefore not keyed; short versus long acting is."},
{"id": "DL2-040", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "tiotropium-heart-rate", "tags": ["drug-list"], "source": "both", "stem": "Inhaled tiotropium is unlikely to change heart rate. Which of the following is the reason?", "options": [{"t": "It stays mainly in the lungs", "correct": true, "why": "Its structure gives very low bioavailability, so it stays in the airways and rarely reaches M2 in the heart."}, {"t": "It does not bind M2 receptors", "correct": false, "why": "Tiotropium is one of the less selective inhaled antagonists; it could affect M2 if it got into the circulation."}, {"t": "It is an agonist at M2 in the heart", "correct": false, "why": "Tiotropium is a muscarinic antagonist, not an agonist."}, {"t": "It activates β1 receptors in the heart", "correct": false, "why": "β1 is an adrenergic receptor; tiotropium is a muscarinic antagonist."}], "teach": "M2 receptors at the SA and AV node slow the heart, so blocking them would raise heart rate. Tiotropium and ipratropium are less selective inhaled muscarinic antagonists, but their chemical structure gives very low bioavailability, so they stay mainly in the lungs and seldom reach the heart.", "quote": "The ipratropium and the tiotropium are less selective, but what we have done for them is change their chemical structure so that they have very low bioavailability, so they stay primarily within the lungs. So even though they can affect the M2s or the M3s, it's very likely, unlikely because they don't get systemic.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 10, 28; transcript 10/5", "note": "The drug list says heart rate is not affected because tiotropium does not target M2, and the slide gives tiotropium as M1 and M3. On 10/5 he said tiotropium is less selective and could affect M2 if it went systemic, and that its low bioavailability keeps it in the lungs. Keyed to what he said."},
{"id": "DL2-041", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "aclidinium", "tags": ["drug-list"], "source": "both", "stem": "Which statement about aclidinium and umeclidinium is CORRECT?", "options": [{"t": "They have high affinity for M3 and dissociate slowly", "correct": true, "why": "They bind M3 tightly (high affinity); binding is reversible, but dissociation is slow, so they are very long acting. Site of action: the lungs."}, {"t": "They are irreversible M3 antagonists", "correct": false, "why": "They are reversible, with slow dissociation."}, {"t": "They are muscarinic agonists for dry mouth", "correct": false, "why": "The muscarinic agonist used for dry mouth is pilocarpine."}, {"t": "They act on M3 in the bladder for overactive bladder", "correct": false, "why": "That is oxybutynin and the other overactive-bladder drugs; aclidinium and umeclidinium are inhaled and act in the lungs."}], "teach": "Aclidinium and umeclidinium are inhaled muscarinic antagonists acting in the lungs. They bind M3 with high affinity and are more selective for M3 than ipratropium and tiotropium; the binding is reversible, but they dissociate slowly, so they are very long acting (long-acting muscarinic antagonists).", "quote": "And we have two drugs, the clinidiums in the bottom. Those are really long acting. … So they have a very high tight binding, so a very high affinity, and they're more selective to the M3s.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 28; transcript 10/5"},
{"id": "DL2-042", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "soa-lungs", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which muscarinic antagonists have the lungs as their site of action? Select all that apply.", "options": [{"t": "Ipratropium", "correct": true, "why": "Inhaled and built for very low bioavailability, so it stays in the lungs (short-acting muscarinic antagonist)."}, {"t": "Tiotropium", "correct": true, "why": "Inhaled and built for very low bioavailability, so it stays in the lungs (long-acting muscarinic antagonist)."}, {"t": "Umeclidinium", "correct": true, "why": "Inhaled; it binds lung M3 tightly (high affinity, slow dissociation), so it is very long acting."}, {"t": "Oxybutynin", "correct": false, "why": "Its site of action is M3 in the bladder (overactive bladder), not the lungs."}, {"t": "Tropicamide", "correct": false, "why": "Its site of action is the eye: M3 block dilates the pupil."}, {"t": "Benztropine", "correct": false, "why": "Its site of action is the brain (M1), as an add-on in Parkinson’s disease."}], "teach": "The inhaled muscarinic antagonists (less systemic effect) are ipratropium, tiotropium, aclidinium and umeclidinium. In the lungs only the parasympathetic system innervates bronchial smooth muscle, where M3 causes bronchial constriction.", "quote": "So for example, if your patient has COPD and they use an inhaler, where do you want the drug to be at? In the lungs. … so that they have very low bioavailability, so they stay primarily within the lungs.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3–4; PCOL-Cholinergic-26s.pdf slide 27–28; transcript 10/5"},
{"id": "DL2-043", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-oab", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of oxybutynin?", "options": [{"t": "Muscarinic antagonist favoring M3", "correct": true, "why": "Oxybutynin and the other overactive-bladder drugs are non-selective, reversible muscarinic antagonists that are more selective toward bladder M3."}, {"t": "β3 agonist in bladder smooth muscle", "correct": false, "why": "That is mirabegron, which relaxes the bladder through β3 (Gs); oxybutynin works by blocking M3."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is bethanechol, which contracts the bladder through M3; oxybutynin blocks that receptor."}, {"t": "α1 antagonist in the urethra", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin (adrenergic); oxybutynin acts on muscarinic M3."}], "teach": "Oxybutynin, trospium and solifenacin are reversible muscarinic antagonists designed to be more selective toward the M3 receptors in the bladder. Blocking bladder M3 relaxes the bladder and decreases urgency, frequency and leakage in overactive bladder.", "quote": "So by giving this muscarinic antagonist and blocking the M3s in the bladder, we're gonna relax the bladder so you don't have that urgency of having to go potty all the time. … these drugs, they are designed, bless you, to be more selective to the M3s in the bladder", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 29; transcript 10/5"},
{"id": "DL2-044", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "oab-cns", "tags": ["drug-list", "tell"], "source": "both", "stem": "Which statement about oxybutynin and solifenacin is CORRECT?", "options": [{"t": "Oxybutynin is more likely to cause sedation", "correct": true, "why": "Oxybutynin is less selective: it blocks M1 in the brain as well as M3, so it causes sedation; solifenacin is more selective for M3."}, {"t": "Solifenacin is more likely to cause sedation", "correct": false, "why": "Reversed: solifenacin is the more M3-selective drug, with fewer central effects."}, {"t": "Only oxybutynin can cause anti-DUMBBELSS", "correct": false, "why": "All of them can; a high enough dose of solifenacin gives all the anti-DUMBBELSS effects."}, {"t": "Both act mainly on M2 in the bladder", "correct": false, "why": "The bladder target is M3; M2 is the cardiac muscarinic receptor."}], "teach": "All overactive-bladder antagonists can cause anti-DUMBBELSS, especially dry mouth and constipation (M3). Central effects (drowsiness, dizziness, confusion) follow M1 block: oxybutynin (M1 and M3, the oldest and cheapest) most, and least the M3-selective solifenacin and trospium. At therapeutic doses the M3-selective drugs act more on the bladder and cause fewer anti-DUMBBELSS effects; at higher doses they cause them all.", "quote": "Now, oxybutynin over here, uh, when we look at their anti-muscarin effect, they are less selective. They can affect the M1s and they can affect the M3s. What effect they would have by affecting the M1s? What would be the site of action? The brain, right? So they'll cause sedation.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/5", "note": "The drug list says solifenacin, darifenacin and trospium are “least likely to cause anti-DUMBBELSS”; the slide says all of them can cause anti-DUMBBELSS and places the three lowest for central effects. On 10/5 he said both: the M3-selective drugs cause fewer anti-DUMBBELSS effects at therapeutic doses, but “if I give enough of VESIcare, I’m gonna get all the anti-dumbbells”. He named oxybutynin, trospium and solifenacin as the three overactive-bladder drugs for the exam."},
{"id": "DL2-045", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-oab", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which adverse effects are shared by all the overactive-bladder muscarinic antagonists? Select all that apply.", "options": [{"t": "Xerostomia (dry mouth)", "correct": true, "why": "All muscarinic antagonists: M3 block on salivary glands."}, {"t": "Constipation", "correct": true, "why": "All muscarinic antagonists: M3 block in the gut."}, {"t": "Diarrhea", "correct": false, "why": "Diarrhea is a muscarinic agonist (DUMBBELSS) effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is an agonist effect; antagonists dilate the pupil."}, {"t": "Bradycardia", "correct": false, "why": "Bradycardia is an agonist effect (M2); antagonists raise heart rate."}], "teach": "All overactive-bladder antagonists (oxybutynin, trospium, solifenacin and the others) have the potential to cause anti-DUMBBELSS; the more M3-selective ones need a higher dose to do so. The effects shared by all muscarinic antagonists through M3 are xerostomia (dry mouth) and constipation.", "quote": "If I give enough of VESIcare, I'm gonna get all the anti-dumbbells.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/5", "level": 1},
{"id": "DL2-046", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "moa-nitrates", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of nitroglycerin?", "options": [{"t": "Donates nitric oxide, which raises cGMP", "correct": true, "why": "Listed: donate nitric oxide; nitric oxide → soluble guanylyl cyclase (sGC) → ↑ cyclic guanosine monophosphate (cGMP)."}, {"t": "Blocks phosphodiesterase, which raises cGMP", "correct": false, "why": "That is sildenafil, tadalafil and vardenafil, which slow cGMP breakdown; nitroglycerin adds nitric oxide, which makes more cGMP."}, {"t": "Activates M3 receptors on the endothelium", "correct": false, "why": "That is a muscarinic agonist; nitroglycerin donates nitric oxide itself."}, {"t": "Blocks α1 receptors on blood vessels", "correct": false, "why": "That is prazosin and the other α1 antagonists, which dilate without nitric oxide or cGMP."}], "teach": "Nitroglycerin, nitroprusside and isosorbide dinitrate/mononitrate are nitric oxide donors. Nitric oxide activates soluble guanylyl cyclase (sGC), which raises cyclic guanosine monophosphate (cGMP), a potent vasodilator; the result is vasodilation and lower blood pressure.", "quote": "It's either nitroglycerin or nitro pruide, so they are what we call nitric oxide donors. As these drugs get metabolized, they give away nitric oxide, and nitric oxide can then go and do its business, OK.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 62, 67; transcript 10/7", "note": "The drug list gives the site of action as “Endothelium of blood vessels (M3)”; on 10/7 he said the nitric oxide from nitroglycerin bypasses the endothelial M3 and NOS steps and goes straight to soluble guanylyl cyclase in the smooth muscle. The M3 site is not keyed."},
{"id": "DL2-047", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "moa-pde", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of sildenafil?", "options": [{"t": "Blocks phosphodiesterase, so cGMP rises", "correct": true, "why": "Listed: blocks phosphodiesterase (PDE), the enzyme that breaks down cyclic guanosine monophosphate (cGMP), so there is more cGMP."}, {"t": "Donates nitric oxide, so cGMP rises", "correct": false, "why": "That is nitroglycerin, nitroprusside and isosorbide, which make more cGMP; sildenafil slows its breakdown."}, {"t": "Blocks muscarinic M3 receptors on vessels", "correct": false, "why": "That is a muscarinic antagonist; vascular M3 is quiet at rest, and sildenafil acts on the enzyme that breaks down cGMP."}, {"t": "Activates β2 receptors on vascular smooth muscle", "correct": false, "why": "That is the β2 agonists (albuterol and others), which raise cAMP, not cGMP; sildenafil acts on phosphodiesterase."}], "teach": "Sildenafil, tadalafil and vardenafil block phosphodiesterase (PDE), the enzyme that breaks down cyclic guanosine monophosphate (cGMP). More cGMP gives vasodilation and lower blood pressure; they are used for erectile dysfunction. The list colours them as indirect antagonists.", "quote": "So what do you think is going to happen if I give a drug that blocks the PDE? What is going to happen to the potency of nitric oxide? It's gonna increase.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 68–74; transcript 10/7"},
{"id": "DL2-048", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "no", "skill": "drug", "concept": "group-cgmp", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs lower blood pressure by raising cGMP in blood vessels? Select all that apply.", "options": [{"t": "Nitroprusside", "correct": true, "why": "Nitric oxide donor → soluble guanylyl cyclase → ↑ cyclic guanosine monophosphate (cGMP)."}, {"t": "Isosorbide mononitrate", "correct": true, "why": "A nitric oxide donor: nitric oxide activates soluble guanylyl cyclase, so cGMP rises."}, {"t": "Tadalafil", "correct": true, "why": "Blocks phosphodiesterase, the enzyme that breaks down cGMP, so cGMP rises."}, {"t": "Prazosin", "correct": false, "why": "Prazosin lowers blood pressure by blocking α1 receptors, not through cGMP."}, {"t": "Albuterol", "correct": false, "why": "A β2 agonist: it raises cyclic AMP (cAMP), not cGMP."}, {"t": "Atropine", "correct": false, "why": "A muscarinic antagonist; it neither makes nitric oxide nor blocks phosphodiesterase, so cGMP does not rise."}], "teach": "Two groups on the list end in more cyclic guanosine monophosphate (cGMP): nitric oxide donors (nitroglycerin, nitroprusside, isosorbide), which make more of it, and phosphodiesterase blockers (sildenafil, tadalafil, vardenafil), which stop its breakdown. Both give vasodilation and lower blood pressure.", "quote": "I need you to know that if you either activate the M3s on the endothelium or if you take nitroglycerin, you're going to be either producing nitric oxide, and nitric oxide is a powerful vasodilator because it activates the solublegla cyclase and produces cyclic GMP.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 67–74; transcript 10/7", "note": "Bethanechol was replaced by albuterol among the distractors: on 10/7 he taught that a muscarinic agonist acting on endothelial M3 makes nitric oxide and raises cGMP."},
{"id": "DL2-049", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-phenylephrine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of phenylephrine?", "options": [{"t": "α1 agonist", "correct": true, "why": "Phenylephrine activates α1 (Gq, ↑Ca++) in blood vessels and the eye: vasoconstriction and mydriasis."}, {"t": "α2 agonist", "correct": false, "why": "That is clonidine and the other α2 agonists, which suppress sympathetic outflow (Gi); phenylephrine activates α1 (Gq)."}, {"t": "Selective α1 antagonist", "correct": false, "why": "That is prazosin and the other -osins, which block the receptor phenylephrine activates."}, {"t": "β1 agonist", "correct": false, "why": "That is dobutamine, acting on the heart; phenylephrine constricts vessels through α1."}], "teach": "Phenylephrine activates α1 receptors (Gq, ↑Ca++) on blood vessels (vasoconstriction; nasal decongestant; higher preload and afterload) and in the eye (mydriasis). Its adverse reactions are burning, blurred vision, rebound congestion and higher blood pressure (care in patients with hypertension).", "quote": "on the selective side, I have phenyphrine as a selected alpha 1 agonist. Pheenyphrine sounds like epinephrine, norepinephrine, so you know it's affecting the alpha 1 receptor in a way. … Yes, it's an agonist to the alpha 1, so it's gonna activate it and it's gonna activate the GQ pathway which is gonna increase calcium inside of those smooth muscles which leads to vasoconstriction, right.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 9, 17–18; transcript 10/6"},
{"id": "DL2-050", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-phenylephrine", "tags": ["drug-list"], "source": "both", "stem": "Phenylephrine used as a nasal decongestant is most likely to cause which of the following?", "options": [{"t": "Rebound congestion", "correct": true, "why": "A known adverse reaction of the α1 decongestant; he warned not to use it for more than 3 days."}, {"t": "Orthostatic hypotension followed by reflex tachycardia", "correct": false, "why": "That is the α1 antagonists (prazosin and others), which dilate vessels; phenylephrine constricts them."}, {"t": "Dry mouth", "correct": false, "why": "Dry mouth is the common complaint with clonidine (α2 agonist)."}, {"t": "Hypertensive crisis on abrupt withdrawal", "correct": false, "why": "That is clonidine (receptor up-regulation)."}], "teach": "Phenylephrine’s adverse reactions are burning, blurred vision, rebound congestion (do not use for more than 3 days) and higher blood pressure, so care is needed in patients with hypertension. The list attributes the rebound congestion to receptor down-regulation; that cause was not given in lecture.", "quote": "And then there are some side effects associated with that, which of course if you put anything in the eye, it's going to cause some burning, blurred vision, uh, you may have rebound congestion. As such, if you read in the back of the box, it tells you you don't use for more than 3 days.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 18; transcript 10/6", "note": "The drug list gives the cause of rebound congestion as receptor down-regulation; in lecture he gave the warning (do not use for more than 3 days) but not the cause. Not keyed."},
{"id": "DL2-051", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-cocaine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of cocaine?", "options": [{"t": "Norepinephrine reuptake inhibitor", "correct": true, "why": "Cocaine blocks the norepinephrine transporter (NET), so norepinephrine stays in the synapse and activates postsynaptic receptors: an indirect-acting drug."}, {"t": "Stimulates presynaptic release of norepinephrine and dopamine", "correct": false, "why": "That is amphetamine and methylphenidate, which push norepinephrine out; cocaine blocks its reuptake."}, {"t": "Irreversible inhibitor of MAO-A and MAO-B", "correct": false, "why": "That is phenelzine, which blocks the breakdown of norepinephrine by monoamine oxidase; cocaine blocks reuptake."}, {"t": "α1 agonist", "correct": false, "why": "That is phenylephrine, a direct agonist; cocaine acts indirectly, on reuptake."}], "teach": "Cocaine is a reuptake inhibitor: it blocks the norepinephrine transporter (NET), so more norepinephrine stays in the synapse and activates the postsynaptic receptors. Effects: severe vasoconstriction in blood vessels (α1; nosebleeds and septum damage when snorted), excitation in the central nervous system, and a faster heart that can lead to a heart attack.", "quote": "So cocaine is a reuptake inhibitor. This drug blocks the net transporter, and if I block the net transporter, what is going to happen to the levels of norepinephrine? Would increase, which means is it's gonna cause what activation of those postsynaptic receptors, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 10; transcript 10/6", "note": "The drug list says cocaine is “used with lidocaine to control arrythmias (Na+ channel blocker)”. On 10/6 he said the opposite: cocaine (or epinephrine) is added to lidocaine as a vasoconstrictor to decrease bleeding and keep lidocaine from reaching the heart, where it can cause arrhythmias. Not asked here (uses are not tested); see L10-022."},
{"id": "DL2-052", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-amphetamine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the primary mechanism of action of methylphenidate?", "options": [{"t": "Stimulates release of norepinephrine and dopamine", "correct": true, "why": "Like the amphetamines, methylphenidate pushes norepinephrine and dopamine (and, he added, serotonin) out of the presynaptic terminal; it does not bind the receptors."}, {"t": "Norepinephrine reuptake inhibitor", "correct": false, "why": "That is cocaine, a complete NET blocker; the amphetamine-like drugs inhibit reuptake only weakly, as a secondary action."}, {"t": "Selective, irreversible monoamine oxidase B inhibitor", "correct": false, "why": "That is selegiline, which blocks the breakdown of norepinephrine; methylphenidate pushes it out of the terminal."}, {"t": "Central α2 agonist", "correct": false, "why": "That is clonidine and guanfacine, which suppress norepinephrine release, the opposite of methylphenidate."}], "teach": "Dextroamphetamine/amphetamine, methylphenidate, lisdexamphetamine and dexmethylphenidate work mainly by stimulating presynaptic release of norepinephrine, dopamine and serotonin, with weak-to-moderate inhibition of reuptake and of monoamine oxidase. More sympathetic outflow gives higher blood pressure and heart rate, tremor, sweating and loss of appetite.", "quote": "So they do not work typically by binding and activating the receptors. They are indirectly enhancing the release, so they stimulate the release of catecholamine, such as norepinephrine, serotonin, and dopamine, OK?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 11; transcript 10/6"},
{"id": "DL2-053", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenelzine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about phenelzine is CORRECT?", "options": [{"t": "It can cause a hypertensive crisis with dietary tyramine", "correct": true, "why": "With MAO-A and MAO-B blocked irreversibly, tyramine from fermented foods is not broken down: a hypertensive crisis (the “cheese effect”)."}, {"t": "It is a selective, reversible monoamine oxidase B inhibitor", "correct": false, "why": "Phenelzine is non-selective (MAO-A and MAO-B) and irreversible; selegiline is the selective MAO-B drug."}, {"t": "It blocks norepinephrine reuptake", "correct": false, "why": "Blocking reuptake through the NET is cocaine; phenelzine blocks the enzyme that breaks norepinephrine down."}, {"t": "It is a direct α1 agonist", "correct": false, "why": "That is phenylephrine; phenelzine acts indirectly, on monoamine oxidase."}], "teach": "Phenelzine irreversibly inhibits both monoamine oxidase A and B (MAO-A and MAO-B), so the breakdown of norepinephrine is inhibited. Its serious adverse reaction is a hypertensive crisis from dietary tyramine in fermented foods (cheese, bread, wine): the “cheese effect”.", "quote": "We have the non-selectives, and I picked phenelzine as our prototypical drug. This drug is an irreversible antagonist, which means is, once you bind that enzyme, your body has to make new ones. … you have the inability to break down that dietary tyramine that you're consuming, and those fermented foods have high levels of tyramine, and that can cause what is called a hypertensive crisis.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 14–15; transcript 10/6", "level": 2},
{"id": "DL2-054", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mao-tell", "tags": ["drug-list", "tell"], "source": "both", "stem": "Which drug is a selective, irreversible inhibitor of monoamine oxidase B (MAO-B)?", "options": [{"t": "Selegiline", "correct": true, "why": "Selegiline: selective MAO-B irreversible antagonist (low doses)."}, {"t": "Phenelzine", "correct": false, "why": "Phenelzine inhibits both MAO-A and MAO-B (non-selective)."}, {"t": "Cocaine", "correct": false, "why": "Cocaine is a norepinephrine reuptake inhibitor, not a monoamine oxidase inhibitor."}, {"t": "Mirtazapine", "correct": false, "why": "Mirtazapine is an α2 (and α1, muscarinic, H1) antagonist."}], "teach": "Both monoamine oxidase (MAO) drug groups inhibit breakdown of norepinephrine and are irreversible. Phenelzine blocks MAO-A and MAO-B (non-selective); selegiline blocks MAO-B (B for brain) selectively, so it carries no tyramine “cheese effect”.", "quote": "And then we have a better MAO inhibitor, uh, selegiline, which is selective to the MAOB. … So there is no cheese effect with the selective irreversible MAOB inhibitors in that process.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 14–15; transcript 10/6", "note": "The drug list adds rasagiline as a second selective MAO-B inhibitor; the deck and the 10/6 lecture name only selegiline (“low doses”), so rasagiline is not asked."},
{"id": "DL2-055", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-indirect-reuptake-release", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs raise synaptic norepinephrine indirectly rather than binding adrenergic receptors? Select all that apply.", "options": [{"t": "Cocaine", "correct": true, "why": "It blocks the norepinephrine transporter (NET), so released norepinephrine stays in the synapse."}, {"t": "Methylphenidate", "correct": true, "why": "Stimulates presynaptic release of norepinephrine and dopamine."}, {"t": "Phenelzine", "correct": true, "why": "Inhibits monoamine oxidase, the enzyme that breaks down norepinephrine."}, {"t": "Selegiline", "correct": true, "why": "It inhibits monoamine oxidase B (MAO-B), so less norepinephrine is broken down."}, {"t": "Phenylephrine", "correct": false, "why": "It binds α1 itself (a direct agonist); it does not change norepinephrine levels."}, {"t": "Clonidine", "correct": false, "why": "It binds α2 itself (a direct agonist) and lowers norepinephrine release."}, {"t": "Prazosin", "correct": false, "why": "It binds α1 itself and blocks it (a direct antagonist)."}], "teach": "The indirect adrenergic drugs act on norepinephrine handling, not on the receptor: cocaine blocks reuptake through the norepinephrine transporter; amphetamines and methylphenidate stimulate release; phenelzine and selegiline inhibit breakdown by monoamine oxidase (MAO). Each one leaves more norepinephrine at the receptors, so the effects are sympathetic: higher blood pressure and heart rate. The direct drugs (phenylephrine, clonidine, prazosin) bind the receptor themselves.", "quote": "The other ones over here that are indirectly we have the amphetamine-like drugs. … We have drugs like cocaine that are used recreationally … And then we have some of the MAO inhibitors that by blocking the enzyme that breaks down catecholamines, we can increase the levels in the brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 9; transcript 10/6", "note": "Rasagiline (drug list only) was replaced by selegiline, the MAO-B inhibitor he taught on 10/6."},
{"id": "DL2-056", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-prazosin", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of doxazosin?", "options": [{"t": "Selective, reversible α1 antagonist", "correct": true, "why": "Prazosin, terazosin, doxazosin and tamsulosin (α1a) are selective, reversible α1 antagonists."}, {"t": "Non-selective, irreversible α1 and α2 antagonist", "correct": false, "why": "That is phenoxybenzamine (covalent bond); the -osins are selective and reversible."}, {"t": "α2 agonist", "correct": false, "why": "That is clonidine and the related α2 agonists, which lower sympathetic outflow from the brain; doxazosin blocks α1 in the periphery."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol; doxazosin blocks α1 only."}], "teach": "Prazosin, terazosin, doxazosin and tamsulosin block α1 receptors selectively and reversibly (tamsulosin is listed for α1a). Sites listed: brain, eye, nose, blood vessels and urethra. Blocking α1 on blood vessels decreases preload and afterload.", "quote": "So this is a reversible antagonist that is highly selective to the alpha ones. … For our exam purpose, all I need to know if you see a drug with OC is a selective alpha-1 antagonist.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 27–28; transcript 10/6"},
{"id": "DL2-057", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-alpha1-block", "tags": ["drug-list"], "source": "both", "stem": "Prazosin is most likely to cause which of the following?", "options": [{"t": "Orthostatic hypotension leading to reflex tachycardia", "correct": true, "why": "Blocking α1 dilates veins (blood pools on standing) and arteries; the baroreceptors then speed the heart."}, {"t": "Rebound congestion", "correct": false, "why": "That follows overuse of phenylephrine, an α1 agonist; an α1 antagonist worsens nasal congestion directly."}, {"t": "Hypertensive crisis when the drug is stopped abruptly", "correct": false, "why": "That is the α2 agonists (clonidine and others, receptor up-regulation); prazosin’s problem is the first dose."}, {"t": "Dry mouth", "correct": false, "why": "Dry mouth is the common complaint with clonidine (α2 agonist)."}], "teach": "Blocking α1 relaxes veins (blood pools, orthostatic hypotension and syncope, the first-dose effect) and arteries (the baroreceptors respond with reflex tachycardia). Blurred vision (α1 in the eye) and headache (common to vasodilators) complete the slide’s list; the drug list adds sexual dysfunction.", "quote": "So we have that first dose effect that is gonna cause the reflex tachycardia because your barrels are gonna sense that your blood pressure is too low. You can't get enough blood to the heart, not enough blood to the head.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 30; transcript 10/6"},
{"id": "DL2-058", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenoxybenzamine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about phenoxybenzamine is CORRECT?", "options": [{"t": "It blocks α1 and α2 irreversibly", "correct": true, "why": "It forms covalent bonds with α1 and α2, so released norepinephrine cannot outcompete it and the effect lasts longer."}, {"t": "It blocks α1 selectively and reversibly", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin; phenoxybenzamine is non-selective and covalently bound."}, {"t": "It activates α2 receptors in the brain", "correct": false, "why": "Activating central α2 is clonidine and the related agonists."}, {"t": "It blocks β1 and β2 receptors", "correct": false, "why": "That is propranolol, pindolol and timolol; phenoxybenzamine blocks α receptors."}], "teach": "Phenoxybenzamine blocks α1 and α2 non-selectively and irreversibly, which decreases peripheral resistance and gives a longer duration of action. The list notes its α2 block on parasympathetic fibers causes gastrointestinal stimulation, and that it can control a phenelzine hypertensive crisis short term.", "quote": "This is an irreversible non-selective alpha 1, alpha 2 adrenergic receptor antagonist, which means it's going to form covalent bonds. … So by permanently blocking with covalent bonds, that means that I can produce all the epi and norepinephrine that I want, I can't outcompete those because I'm covalently bound to it.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5–6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 34–35; transcript 10/7", "note": "The drug list adds “longer duration of action (irreversible → highest affinity for α1)”; slides 34–38 do not say it, and on 10/7, when a student said he had stated that phenoxybenzamine works on α1 better than α2, he answered “I don’t recall saying that.” Not keyed."},
{"id": "DL2-059", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "phenoxybenzamine-gi", "tags": ["drug-list", "apply"], "source": "both", "stem": "Phenoxybenzamine causes gastrointestinal (GI) stimulation. Which mechanism explains it?", "options": [{"t": "α2 on parasympathetic fibers is blocked", "correct": true, "why": "Norepinephrine on α2 (Gi) on the parasympathetic nerve normally cuts acetylcholine release; with that brake blocked, more acetylcholine reaches gut M3."}, {"t": "α1 receptors on gut smooth muscle are activated", "correct": false, "why": "Phenoxybenzamine is an antagonist; it does not activate receptors."}, {"t": "Acetylcholinesterase in the gut is inhibited", "correct": false, "why": "That is the cholinesterase inhibitors (the -stigmines); phenoxybenzamine acts on adrenergic receptors, not the enzyme."}, {"t": "M3 receptors in the gut are blocked", "correct": false, "why": "Blocking gut M3 causes constipation, not stimulation."}], "teach": "In the gut, sympathetic norepinephrine acts on α2 (Gi, inhibitory) on the parasympathetic (PNS) nerve terminal and cuts acetylcholine release. Phenoxybenzamine blocks α2 irreversibly and removes that brake, so more acetylcholine reaches gut M3: cramping and diarrhea. An α2 agonist such as clonidine does the opposite: less acetylcholine and constipation.", "quote": "Typically, the sympathetic inhibits the parasympathetic by releasing norepinephrine, which would bind to the alpha-2 receptor on the parasympathetic nerve. Alpha 2s are G alphai, which means they're gonna be inhibitory. … However, phenoxybenzamine is an irreversible alpha 2 antagonist. So if I block that, I take away the inhibition. Now too much parasympathetic tone, cramping, diarrhea, and so on.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 36–38; transcript 10/7", "level": 1},
{"id": "DL2-060", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirtazapine", "tags": ["drug-list"], "source": "both", "stem": "Which receptor does mirtazapine block to cause drowsiness?", "options": [{"t": "H1", "correct": true, "why": "Blocking H1 (with muscarinic receptors) in the brain causes sedation and drowsiness."}, {"t": "α1", "correct": false, "why": "Mirtazapine blocks α1 too, but that relaxes peripheral vessels (edema); the sedation is from H1 block."}, {"t": "α2", "correct": false, "why": "α2 block enhances release of norepinephrine and serotonin, the antidepressant effect, not sedation."}, {"t": "β1", "correct": false, "why": "Mirtazapine does not act at β receptors; β1 is in the heart and kidney."}], "teach": "Mirtazapine is a non-selective antagonist at α2, α1, muscarinic and H1 receptors (the list adds 5-HT2a), acting in the central nervous system. α2 block enhances release of norepinephrine and serotonin; blocking H1 and muscarinic receptors causes drowsiness (sedation).", "quote": "Furthermore, this drug blocks histamine and muscarinic type one in the brain. What is the side effect of having a drug that blocks the muscarinic and the histamine receptors? Sedation, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 31–32; transcript 10/6", "note": "The drug list ties drowsiness to H1 block; on 10/6 he named histamine and muscarinic block for the sedation (slide 33 also lists “Blockade of Muscarinic & Histamine (H1)”). H1 is keyed; muscarinic is not among the options.", "level": 1},
{"id": "DL2-061", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirtazapine-edema", "tags": ["drug-list", "apply"], "source": "both", "stem": "Why does mirtazapine cause peripheral edema?", "options": [{"t": "α1 block relaxes the peripheral vessels", "correct": true, "why": "Blocking α1 (Gq) removes the sympathetic constriction of the peripheral vessels; slide 33 and his 10/7 words give it as the cause of the edema."}, {"t": "H1 block in the brain causes fluid retention", "correct": false, "why": "H1 block in the brain (with muscarinic block) causes drowsiness, not edema."}, {"t": "Muscarinic block in the gut causes edema", "correct": false, "why": "Muscarinic block gives xerostomia and constipation (M3), not edema."}, {"t": "More norepinephrine release constricts the veins", "correct": false, "why": "More norepinephrine release (α2 block) is tied to hypertension, not edema."}], "teach": "Mirtazapine’s adverse reactions follow its receptors: drowsiness (muscarinic and H1 block), weight gain and increased cholesterol (serotonin), xerostomia and constipation (muscarinic block), peripheral edema (α1 block) and hypertension (more norepinephrine release). The α1 and norepinephrine effects pull in opposite directions, so blood pressure varies from patient to patient.", "quote": "and uh you can get peripheral edema by blocking the alpha-1s, but that can be overcome by increase of the sympathetic and norepinephrine which causes increase in blood pressure. So it varies from patient to patient.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 33; transcript 10/7", "note": "The drug list blames peripheral edema on α2 block in small blood vessels; slide 33 (“Peripheral edema — Blockade of alpha 1”) and the 10/7 lecture give α1 block. Keyed to the slide and his words.", "level": 1},
{"id": "DL2-062", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-clonidine", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of guanfacine?", "options": [{"t": "α2 agonist", "correct": true, "why": "Like clonidine, guanfacine activates α2 (Gi) in the brain and suppresses sympathetic outflow."}, {"t": "α2 antagonist", "correct": false, "why": "Blocking α2 (mirtazapine) increases norepinephrine release; guanfacine activates α2 and suppresses it."}, {"t": "α1 agonist", "correct": false, "why": "Activating α1 (phenylephrine) constricts vessels; guanfacine acts centrally on α2."}, {"t": "Selective α1 antagonist", "correct": false, "why": "That is prazosin and the other -osins, which dilate by blocking α1; guanfacine lowers sympathetic outflow through α2."}], "teach": "The α2 agonists act in the central nervous system, where they enhance inhibition and suppress the sympathetic nervous system. Their listed adverse reactions are sedation, dry mouth, hypotension, bradycardia, sexual dysfunction, depression and constipation.", "quote": "So here are our list for our alpha 2 agonists, but if you know clonidine, most of these drugs when needine, it's gonna be an alpha 2 agonist. … we add the Intuniv, which is a similar drug to it", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 21–22; transcript 10/6", "note": "Guanfacine does not end in -idine; on 10/6 he named it (as Intuniv) “a similar drug to it” (clonidine). For the exam he focuses on clonidine as the prototype."},
{"id": "DL2-063", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "clonidine-withdrawal", "tags": ["drug-list", "apply"], "source": "both", "stem": "A patient stops clonidine abruptly. Which of the following is most likely to occur, and why?", "options": [{"t": "Hypertensive crisis, from up-regulated receptors", "correct": true, "why": "Long-term suppression makes the body up-regulate receptors; stopping abruptly lets norepinephrine flood them: a hypertensive crisis, so patients are weaned off."}, {"t": "Bradycardia, from extra parasympathetic tone", "correct": false, "why": "Stopping clonidine removes the brake on the sympathetic system; pressure and heart rate rise."}, {"t": "Rebound congestion, from down-regulated α1 receptors", "correct": false, "why": "That follows overuse of phenylephrine in the nose; clonidine acts on α2 in the brain."}, {"t": "Orthostatic hypotension, from α1 block", "correct": false, "why": "That is the first-dose effect of prazosin; stopping clonidine raises pressure instead."}], "teach": "Clonidine activates central α2 receptors and suppresses sympathetic outflow. During treatment the receptors up-regulate, so stopping the drug abruptly can cause a hypertensive crisis.", "quote": "So what is the one education point that you have to make to your patients? You got to wean yourself off because if you go cold turkey, you got all these receptors, now norepinephrine is flowing like there's no tomorrow, and you go into a hypertensive crisis, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 26; transcript 10/6", "level": 3},
{"id": "DL2-064", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-alpha2-agonist", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Clonidine is most likely to cause which of the following? Select all that apply.", "options": [{"t": "Sedation", "correct": true, "why": "α2 activation in the brain inhibits the central nervous system: sedation."}, {"t": "Dry mouth", "correct": true, "why": "One of the most common complaints with the α2 agonists."}, {"t": "Bradycardia", "correct": true, "why": "Less sympathetic outflow to the heart lowers heart rate."}, {"t": "Hypotension", "correct": true, "why": "Less sympathetic outflow relaxes arteries and veins and lowers cardiac output, so blood pressure falls."}, {"t": "Tachycardia and arrhythmias", "correct": false, "why": "Those follow from more sympathetic drive, as with cocaine and the amphetamines."}, {"t": "Rebound nasal congestion", "correct": false, "why": "That follows overuse of phenylephrine, an α1 agonist in the nose; clonidine acts on α2."}], "teach": "α2 agonists suppress the sympathetic nervous system from the central nervous system. Listed reactions: sedation, dry mouth, hypotension, bradycardia, sexual dysfunction, depression and constipation (the list says through a gastrointestinal inhibitory feedback pathway → less acetylcholine).", "quote": "So when it comes to side effects, the most common side effects with this drug can be sedation because you're inhibiting the CNS. Patients may complain of nightmares and maybe depression. Dry mouth is very common. … lower blood pressure, lower heart rate, so hypertension and bradycardia can be severe if the dose is too high.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 26; transcript 10/6"},
{"id": "DL2-065", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-dobutamine", "tags": ["drug-list"], "source": "both", "stem": "Which drug is a selective β1 agonist?", "options": [{"t": "Dobutamine", "correct": true, "why": "Slide 40: selective β1 agonist (+ inotropic action and increased heart rate)."}, {"t": "Isoproterenol", "correct": false, "why": "Isoproterenol activates β1 and β2 equally (“iso” = equal), so it is not selective."}, {"t": "Albuterol", "correct": false, "why": "Albuterol (a -terol) activates lung β2, not heart β1."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is selective for β1, but it blocks the receptor rather than activating it."}], "teach": "Dobutamine activates β1 in the heart: stronger contraction and higher heart rate. It is given intravenously for short-term cardiac decompensation; tolerance (receptor down-regulation) limits long-term use, and its major adverse reactions are tachycardia and arrhythmias. The list adds that at high dose it acts at β1 > β2 > α1, and increased renin–angiotensin–aldosterone system (RAAS) activity and central nervous system stimulation.", "quote": "We can activate the system through a selective beta1 ago agonist, such as dobutamine. This is an IV drug. We're really going to use this drug in a very, uh, you know, ICU ER situation.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 40–41; transcript 10/7", "note": "The drug list’s dose wording (low dose β1 selective; high dose β1 > β2 > α1) is not on slides 40–41 and he did not say it; the stem asks only for the selective β1 agonist (slide 40)."},
{"id": "DL2-066", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-metoprolol", "tags": ["drug-list"], "source": "both", "stem": "Atenolol, metoprolol and nebivolol (“MAN”) share which mechanism of action?", "options": [{"t": "Selective β1 antagonist", "correct": true, "why": "MAN (metoprolol, atenolol, nebivolol) block β1 selectively and leave lung β2 alone."}, {"t": "Non-selective β1 and β2 antagonist", "correct": false, "why": "That is propranolol, pindolol and timolol, which also block lung β2."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol; the MAN drugs block neither α1 nor β2."}, {"t": "β1 agonist", "correct": false, "why": "That is dobutamine, which activates β1; the MAN drugs block it."}], "teach": "Metoprolol, atenolol and nebivolol block β1 selectively; their listed sites are the heart, kidneys and brain. Adverse reactions follow from β1 block: decreased heart rate and contractility, bradycardia, fatigue or dizziness, decreased renin–angiotensin–aldosterone system (RAAS) activity and central nervous system (CNS) depression.", "quote": "How about if we spell man. Man, right? So, we have metoprolol, atenolol, and nabivolol. Those are gonna be your beta one selectives, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 54; transcript 10/7"},
{"id": "DL2-067", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "adr-beta1-block", "tags": ["drug-list"], "source": "both", "stem": "Atenolol is most likely to cause which of the following?", "options": [{"t": "Bradycardia", "correct": true, "why": "Blocking heart β1 removes the sympathetic drive, so the parasympathetic takes over: slower rate and less force."}, {"t": "Tachycardia", "correct": false, "why": "Tachycardia is a β1 agonist (dobutamine) effect; atenolol blocks β1."}, {"t": "Orthostatic hypotension with reflex tachycardia", "correct": false, "why": "That is the α1 antagonists, which dilate veins and arteries; atenolol slows the heart instead."}, {"t": "Rebound congestion", "correct": false, "why": "That follows overuse of phenylephrine, an α1 agonist in the nose; atenolol acts on heart β1."}], "teach": "Selective β1 antagonists act on the heart, kidneys and brain. Blocking β1 in the heart decreases heart rate and contractility (bradycardia); in the kidney it decreases the renin–angiotensin–aldosterone system (RAAS); in the brain it gives fatigue, dizziness and central nervous system (CNS) depression.", "quote": "So if I block the ability of my norepinephrine to bind and activate the beta ones, because all beta blockers blocks beta ones, who's gonna take over? Parasympathetic. So you're gonna get what? Bradycardia, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 56–59; transcript 10/7", "level": 1},
{"id": "DL2-068", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "terol-beta2", "tags": ["drug-list", "tell", "list"], "source": "both", "multi": true, "stem": "Which drugs are β2 agonists? Select all that apply.", "options": [{"t": "Salmeterol", "correct": true, "why": "A -terol: long-acting β2 agonist (LABA)."}, {"t": "Formoterol", "correct": true, "why": "A -terol: long-acting β2 agonist (LABA)."}, {"t": "Albuterol", "correct": true, "why": "A -terol: short-acting β2 agonist (SABA), the prototype."}, {"t": "Levalbuterol", "correct": true, "why": "A -terol: short-acting β2 agonist (SABA), an isomer of albuterol."}, {"t": "Tiotropium", "correct": false, "why": "Tiotropium is a long-acting muscarinic antagonist, not a β2 agonist."}, {"t": "Mirabegron", "correct": false, "why": "Mirabegron is the β3 agonist in the bladder; it is not a -terol and does not act on lung β2."}, {"t": "Dobutamine", "correct": false, "why": "Dobutamine is the selective β1 agonist acting on the heart, not a -terol."}], "teach": "Every -terol is a β2 agonist: albuterol and levalbuterol are short acting (SABA), salmeterol and formoterol long acting (LABA). For this exam he needs only the class, not short versus long acting. Sites: lungs, vasculature and the central nervous system; effects: bronchial dilation, vasodilation and excitation.", "quote": "If you know that a terol is a beta2 agonist, that's good for me. It doesn't matter if it's short acting or long acting. That's not the point over here. The point over here is for you to identify. Which of these is a beta2 agonist? OK.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 43; transcript 10/7", "note": "Rewritten from “Which drugs are long-acting β2 agonists (LABA)?”: on 10/7 he said short versus long acting is not the point for this exam. He also called albuterol a partial agonist and salmeterol and formoterol full agonists; not asked."},
{"id": "DL2-069", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "soa-beta2", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Albuterol is a β2 agonist. Which of the following effects is it most likely to produce? Select all that apply.", "options": [{"t": "Bronchial dilation", "correct": true, "why": "β2 (Gs) relaxes bronchial smooth muscle."}, {"t": "Vasodilation", "correct": true, "why": "β2 relaxes vascular smooth muscle."}, {"t": "Excitation", "correct": true, "why": "In the central nervous system β2 stimulates: excitation."}, {"t": "Bronchial constriction", "correct": false, "why": "Bronchial constriction comes from M3 activation; β2 dilates."}, {"t": "Bradycardia", "correct": false, "why": "Bradycardia comes from β1 block or M2 activation; β agonists, if anything, speed the heart."}], "teach": "The β2 agonists act on the lungs, vasculature and central nervous system. The listed effects are bronchial dilation, vasodilation and excitation.", "quote": "All right, so in the vascular and bronchius moo muscle, beta 2s are gonna cause dilation. In the CNS it's gonna stimulate.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 42; transcript 10/7", "level": 1},
{"id": "DL2-070", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-propranolol", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of propranolol?", "options": [{"t": "Non-selective β1 and β2 antagonist", "correct": true, "why": "Propranolol, pindolol and timolol are listed as non-selective β blockers (β1 and β2)."}, {"t": "Selective β1 antagonist", "correct": false, "why": "That is metoprolol, atenolol and nebivolol (MAN), which spare lung β2; propranolol blocks both."}, {"t": "β1, β2 and α1 antagonist", "correct": false, "why": "That is carvedilol and labetalol; propranolol does not block α1."}, {"t": "Non-selective α1 and α2 antagonist", "correct": false, "why": "That is phenoxybenzamine, an α blocker; propranolol blocks β receptors."}], "teach": "Propranolol blocks β1 and β2. Its listed sites are the heart, kidneys, brain, lungs and vasculature. Because it blocks β2 in the lungs it is listed as contraindicated in asthma patients, and it masks the nervousness and tremor of hypoglycemia.", "quote": "And then you know that your propranolol, pinolol is your beta 1, beta 2, and then your carvedilol, labetalol is your beta 1, beta 2, and alpha 1, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 54; transcript 10/7", "note": "The drug list says propranolol is given at low dose for anxiety by targeting β1 in the brain; on 10/7 he explained the anxiety effect through β2 in the central nervous system (positive feedback on norepinephrine release). Not asked here; L11-043 keys his version."},
{"id": "DL2-071", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "pindolol", "tags": ["drug-list"], "source": "both", "stem": "Which β blocker is a partial agonist?", "options": [{"t": "Pindolol", "correct": true, "why": "Pindolol blocks β1 and β2 but keeps some intrinsic activity of its own: a partial agonist (“Pindolol (PA)” on slide 54)."}, {"t": "Propranolol", "correct": false, "why": "Propranolol, the prototype non-selective β blocker, is a pure antagonist with no partial agonism."}, {"t": "Timolol", "correct": false, "why": "Timolol is a non-selective β blocker with no partial agonist activity."}, {"t": "Metoprolol", "correct": false, "why": "Metoprolol is a selective β1 antagonist with no partial agonism."}], "teach": "Pindolol sits in the non-selective β-blocker row with propranolol and timolol but is marked as a partial agonist; the Exam 1 list also called it a β1 and β2 partial agonist. A partial agonist activates the receptor submaximally and competes with full agonists.", "quote": "I also include Pinool because you already kind of learned about that, right? That's the partial agonist that we talked about back in for exam one.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54, 59; transcript 10/7", "note": "On 10/7 he said partial agonists were covered for Exam 1 and will not be discussed much for this exam."},
{"id": "DL2-072", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-asthma-beta-blockers", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which of the following β blockers are most likely to worsen asthma? Select all that apply.", "options": [{"t": "Propranolol", "correct": true, "why": "Non-selective: it blocks lung β2, so the airways constrict and more β2-agonist puffs are needed."}, {"t": "Timolol", "correct": true, "why": "Non-selective (β1 and β2): it blocks lung β2 as propranolol does."}, {"t": "Carvedilol", "correct": true, "why": "It blocks lung β2 along with β1 and α1."}, {"t": "Labetalol", "correct": true, "why": "It blocks lung β2 along with β1 and α1."}, {"t": "Metoprolol", "correct": false, "why": "β1 selective: it leaves the lung β2 receptors alone, so it is the choice in asthma."}, {"t": "Atenolol", "correct": false, "why": "β1 selective (“MAN”): lung β2 is left alone."}, {"t": "Albuterol", "correct": false, "why": "A β2 agonist, not a β blocker: it dilates the bronchi."}], "teach": "The drugs that block β2 as well as β1 — propranolol, pindolol, timolol, carvedilol and labetalol — are listed as contraindicated for asthma patients (slide 59: reactive airway disease, non-selective). Blocking lung β2 means more puffs of the β2 agonist are needed to outcompete the blocker. The same non-selective drugs mask more of the warning signs of hypoglycemia (nervousness and tremor).", "quote": "If you have a beta blocker that is non-selective and we're blocking the beta 2, it's going to require more puffs of your saba or your laba to outcompete the beta blocker", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54, 59; transcript 10/7", "note": "Rewritten from the list’s pairing of asthma and hypoglycemia: on 10/7 he said every β blocker masks the tachycardia of hypoglycemia, and the non-selective ones also mask tremor and nervousness. Timolol is on the list and on slide 54 (non-selective) but he did not name it on 10/7.", "level": 1},
{"id": "DL2-073", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "moa-carvedilol", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of labetalol?", "options": [{"t": "β1, β2 and α1 antagonist", "correct": true, "why": "Carvedilol and labetalol are listed as β1 and β2 antagonists and α1 antagonists."}, {"t": "Selective β1 antagonist", "correct": false, "why": "That is metoprolol, atenolol and nebivolol; labetalol also blocks β2 and α1."}, {"t": "Selective, reversible α1 antagonist", "correct": false, "why": "That is prazosin and the related -osins, which block α1 only; labetalol adds β1 and β2."}, {"t": "β3 agonist", "correct": false, "why": "That is mirabegron, which activates bladder β3; labetalol is a blocker."}], "teach": "Carvedilol and labetalol block β1, β2 and α1. Their listed effects follow from β block (decreased heart rate and contractility, bradycardia, fatigue, decreased renin–angiotensin–aldosterone system (RAAS) activity) and they share the asthma contraindication and the masking of hypoglycemia with the non-selective β blockers.", "quote": "I would like for you to know about labetalol and carvedilol. Those are mixed beta blockers. They're gonna block beta ones, beta2s, and alpha ones.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 54; transcript 10/7"},
{"id": "DL2-074", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "mirabegron", "tags": ["drug-list"], "source": "both", "stem": "Which drug is a β3 agonist acting in the bladder?", "options": [{"t": "Mirabegron", "correct": true, "why": "Mirabegron activates β3 (Gs) on bladder smooth muscle, which relaxes it so the bladder holds more urine."}, {"t": "Oxybutynin", "correct": false, "why": "Oxybutynin relaxes the bladder by blocking M3, not by activating β3."}, {"t": "Bethanechol", "correct": false, "why": "Bethanechol is a muscarinic agonist: it contracts the bladder through M3 (more urination)."}, {"t": "Tamsulosin", "correct": false, "why": "Tamsulosin is an α1 (α1a) antagonist acting on the urethra and prostate, not on β3."}], "teach": "Mirabegron activates β3 receptors in the bladder and relieves overactive bladder. The list notes it has fewer side effects than the muscarinic antagonists used for the same problem.", "quote": "The beta 3s, there's only one drug over here, uh, mitaegron, and this is a beta 3 selective agonist.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/7"},
{"id": "DL2-075", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "oab-tell-mirabegron", "tags": ["drug-list", "tell"], "source": "both", "stem": "Two drugs for overactive bladder: oxybutynin and mirabegron. Which statement tells them apart?", "options": [{"t": "Oxybutynin blocks M3; mirabegron activates β3", "correct": true, "why": "Oxybutynin: muscarinic antagonist, more selective for bladder M3. Mirabegron: β3 agonist in the bladder."}, {"t": "Oxybutynin activates β3; mirabegron blocks M3", "correct": false, "why": "Reversed: oxybutynin is the antimuscarinic and mirabegron the β3 agonist."}, {"t": "Both block M3 in the bladder", "correct": false, "why": "Only oxybutynin is a muscarinic antagonist; mirabegron works through β3, so it lacks the anti-DUMBBELSS."}, {"t": "Both activate β3 in the bladder", "correct": false, "why": "Only mirabegron is a β3 agonist."}], "teach": "Oxybutynin is a muscarinic antagonist (more selective toward bladder M3) and can cause anti-DUMBBELSS, especially dry mouth and constipation. Mirabegron is a β3 agonist in the bladder with fewer side effects than the muscarinic antagonists.", "quote": "This drug is more selective to the beta 3s in the bladder and thus doesn't have the side effects of the antimuscarinics, right, like atropine or trospium or VESIcare and all those drugs", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4, 7; PCOL-Cholinergic-26s.pdf slide 29; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 44; transcript 10/7"},
{"id": "DL2-076", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "epinephrine", "tags": ["drug-list"], "source": "both", "stem": "Which statement about epinephrine’s receptor actions is CORRECT?", "options": [{"t": "β1, β2 at low dose; all at high dose", "correct": true, "why": "Listed: low dose β1 & β2; high dose: everything. Slide 47: β1 and β2 at low doses, α1 and α2 at high doses."}, {"t": "α1 only at every dose", "correct": false, "why": "α1 alone is phenylephrine; epinephrine binds β1 and β2 first and reaches α only as the dose rises."}, {"t": "α1 and α2 at low dose; β at high dose", "correct": false, "why": "Reversed: the β receptors have the highest affinity and are reached first."}, {"t": "α2 only, acting in the brain", "correct": false, "why": "α2 agonism in the brain is clonidine and the related drugs."}], "teach": "Epinephrine has different affinities for the adrenergic receptors: β1 and β2 at low doses, then α1 and finally α2 as the dose rises. In blood vessels a low dose dilates (β2) and a high dose constricts (α1 overrides β2); after an α1 blocker such as prazosin, the high dose dilates instead (epinephrine reversal). Patients on an infusion must be weaned off because the receptors down-regulate.", "quote": "At low doses, uh, epinephrine has the highest affinity for the beta 1 and the beta 2 receptor. … So, the, the, the rank of affinity is gonna be beta one beta choose, alpha one, and then alpha 2.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; Autonomic Nervous System.pdf slide 35, 42; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 47; transcript 10/7", "note": "The Exam 1 drug list called epinephrine an α1, α2, β1 and β2 agonist; this list gives β1 and β2 at low dose and all receptors at high dose. Slide 47 of the adrenergic deck and the 10/7 lecture agree with the dose wording (rank: β1, β2, α1, then α2)."},
{"id": "DL2-077", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "norepinephrine", "tags": ["drug-list"], "source": "both", "stem": "Norepinephrine has its highest affinity for which receptors?", "options": [{"t": "α1 and β1", "correct": true, "why": "Listed: α1, β1 agonist; slide 53: binds α1 (vasoconstriction, more total peripheral resistance) and β1 (more heart rate and contractility)."}, {"t": "β1 and β2", "correct": false, "why": "That is isoproterenol, and epinephrine at low doses; norepinephrine prefers α1 and β1."}, {"t": "α2 and β2", "correct": false, "why": "Norepinephrine can bind these, but with lower affinity."}, {"t": "α1 only", "correct": false, "why": "α1 alone is phenylephrine; norepinephrine also raises heart rate and force through β1."}], "teach": "Norepinephrine binds α1 (vasoconstriction, increased total peripheral resistance) and β1 (increased heart rate and myocardial contractility) with the highest affinity; it can also bind α2 and β2. As the sympathetic neurotransmitter it also acts at presynaptic α2. Kept on long term it increases the heart’s oxygen demand and is toxic to the heart, so it is a short-term drug for shock.", "quote": "All right, so norepinephrine is different than Api because norepinephrine appears to have a higher affinity for the beta ones and the alpha ones, OK, than it does for the beta 2s or the alpha 2s. Although it can bind and activate those receptors.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; Autonomic Nervous System.pdf slide 13, 45; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 53; transcript 10/7", "note": "The drug list gives norepinephrine as an α1, β1 agonist, as does slide 53 of the adrenergic deck. Slide 84 of that deck and the autonomic slides add α2 (as the neurotransmitter); on 10/7 he said it has a higher affinity for α1 and β1 than for α2 or β2 “although it can bind and activate those receptors”. Keyed to the highest affinity, so all three sources agree. The Exam 1 drug list called it an α1, α2, β1 and β2 agonist."},
{"id": "DL2-078", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "isoproterenol", "tags": ["drug-list"], "source": "both", "stem": "Which drug is a non-selective β1 and β2 agonist whose adverse reactions include palpitations and tachycardia?", "options": [{"t": "Isoproterenol", "correct": true, "why": "It activates β1 and β2 equally (“iso” = equal): β2 dilates the bronchi, and β1 in the heart gives palpitations, tachycardia and arrhythmias."}, {"t": "Dobutamine", "correct": false, "why": "Dobutamine is the selective β1 agonist; it does not act on β2."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine is an α1 agonist (vasoconstriction) with no β action."}, {"t": "Propranolol", "correct": false, "why": "Propranolol blocks β1 and β2, so it slows the heart instead of causing palpitations."}], "teach": "Isoproterenol activates β1 and β2 with equal affinity (“iso” = equal); its sites are the heart and lungs. β2 gives bronchodilation, but β1 gives palpitations, tachycardia and arrhythmias, which is why albuterol replaced it for asthma.", "quote": "So this is a non-selective beta 1, beta2 agonist. So iso equal, right, equal affinity and efficacy for the beta 1s and the beta 2s. … Yeah, it produced a beautiful bronchodilation, but also the palpitation and tachycardia and arrhythmias", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 45; transcript 10/7", "note": "Hyperglycemia (drug list) is not on slide 45 and he did not mention it; it is no longer in the stem."},
{"id": "DL2-079", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-alpha-block", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs block α1 receptors? Select all that apply.", "options": [{"t": "Terazosin", "correct": true, "why": "An -osin: selective, reversible α1 antagonist."}, {"t": "Prazosin", "correct": true, "why": "An -osin: selective, reversible α1 antagonist."}, {"t": "Carvedilol", "correct": true, "why": "A mixed β blocker: it blocks α1 along with β1 and β2."}, {"t": "Mirtazapine", "correct": true, "why": "It blocks α1 along with α2, muscarinic and H1 receptors (hence peripheral edema)."}, {"t": "Phenylephrine", "correct": false, "why": "Phenylephrine activates α1 (an agonist), so it constricts rather than blocks."}, {"t": "Selegiline", "correct": false, "why": "Selegiline inhibits monoamine oxidase B; it does not block α1."}, {"t": "Clonidine", "correct": false, "why": "Clonidine activates α2 (an agonist); it does not block α1."}], "teach": "α1 block appears in four groups: the selective α1 antagonists (prazosin, terazosin, doxazosin, tamsulosin), phenoxybenzamine (α1 and α2, irreversible), carvedilol and labetalol (with β1 and β2), and mirtazapine (with α2, muscarinic and H1). In each case blocking α1 relaxes vascular smooth muscle, which explains the orthostatic hypotension of the -osins and the peripheral edema of mirtazapine.", "quote": "Carvedilol is a non-selective beta blocker, right? And carvedilol can not only block the beta ones and the beta 2s, but they can also block the alpha ones. … Mirtazapine is our alpha-2 antagonist, but also can block H1s, it can block muscarinics, and it can block alpha-1s.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 5–7; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 7, 27, 31; transcript 10/6", "note": "Carvedilol was named on 10/6 as an example on the MAP-equation slide and taught on 10/7 with labetalol as a β1, β2 and α1 blocker (slide 54). Phenoxybenzamine (irreversible α1 and α2, taught 10/7) is not among the options."},
{"id": "DL2-080", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "adr", "skill": "drug", "concept": "group-beta-agonists", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which drugs are β agonists? Select all that apply.", "options": [{"t": "Dobutamine", "correct": true, "why": "It activates β1 in the heart (Gs)."}, {"t": "Levalbuterol", "correct": true, "why": "A -terol: it activates β2 in the lungs."}, {"t": "Mirabegron", "correct": true, "why": "It activates β3 in the bladder."}, {"t": "Isoproterenol", "correct": true, "why": "It activates β1 and β2 equally."}, {"t": "Metoprolol", "correct": false, "why": "It blocks β1 (MAN): an antagonist, not an agonist."}, {"t": "Nebivolol", "correct": false, "why": "It blocks β1 (MAN): an antagonist, not an agonist."}, {"t": "Labetalol", "correct": false, "why": "It blocks β1, β2 and α1: an antagonist, not an agonist."}], "teach": "The β agonists on the list are dobutamine (β1), albuterol, levalbuterol, salmeterol and formoterol (β2), mirabegron (β3), isoproterenol (β1, β2) and epinephrine (β1, β2 at low dose). Pindolol is listed with the β blockers although marked as a partial agonist.", "quote": "So the easiest part for you is that it doesn't matter if it's a beta 1, a beta 2, or beta 3, they are all linked to GS, which means they're going to stimulate.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 6–8; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 40–45; transcript 10/7", "note": "Pindolol, a partial agonist that he says can “behave like an agonist and behave like an antagonist”, was replaced by metoprolol among the distractors."},
{"id": "DL2-081", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "aliskiren", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of aliskiren?", "options": [{"t": "Selective, reversible renin inhibitor", "correct": true, "why": "Aliskiren binds plasma renin with high affinity and blocks it reversibly; renin is the first, rate-limiting step of the pathway."}, {"t": "Angiotensin-converting enzyme inhibitor", "correct": false, "why": "That is captopril, lisinopril and the other “-prils”, which act one step later, on ACE."}, {"t": "Angiotensin II (AT1) receptor blocker", "correct": false, "why": "That is losartan, valsartan and the other “-sartans”, which act at the end of the cascade, on the receptor."}, {"t": "Mineralocorticoid receptor antagonist", "correct": false, "why": "That is spironolactone and eplerenone, which block aldosterone in the kidney."}], "teach": "Aliskiren is the renin inhibitor: it binds plasma renin with high affinity (enough to work despite a bioavailability of about 2 to 3%) and blocks it reversibly. Renin is the rate-limiting enzyme of the renin–angiotensin–aldosterone system, so everything downstream falls: angiotensin I, angiotensin II, AT1 and AT2 activation, total peripheral resistance and aldosterone.", "quote": "The first one over here is gonna be alicain, and this is gonna be easier for you to remember because you tell it's an antagonist to the renin enzyme, right? … So we can predict that this drug can reversibly inhibit that rest system.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8; PCOL-RAAS_26s.pdf slides 4, 8; transcript 10/8"},
{"id": "DL2-082", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of lisinopril?", "options": [{"t": "Reversible angiotensin-converting enzyme inhibitor", "correct": true, "why": "Every “-pril” selectively and reversibly inhibits ACE, which converts angiotensin I to angiotensin II and breaks down bradykinin."}, {"t": "Reversible angiotensin II type 1 (AT1) receptor blocker", "correct": false, "why": "That is losartan and the other “-sartans”, which block the receptor instead of lowering angiotensin II."}, {"t": "Selective renin inhibitor", "correct": false, "why": "That is aliskiren, which acts one step earlier, on renin."}, {"t": "Selective β1 blocker in the kidney", "correct": false, "why": "That is metoprolol, which lowers renin production through β1 on the juxtaglomerular cells; lisinopril acts on ACE."}], "teach": "Lisinopril, like every “-pril” (captopril, enalapril, benazepril, quinapril, ramipril), inhibits angiotensin-converting enzyme (ACE) selectively and reversibly. Primary effect: angiotensin I is not converted to angiotensin II, so total peripheral resistance, Na+ and water retention and aldosterone fall. Secondary effect: ACE no longer breaks down bradykinin, a potent vasodilator.", "quote": "So the mechanism of action of all the ACE inhibitors, so you just need to know one is gonna be to inhibit the conversion of N1 into H2, OK, so that's gonna be the primary. … so it doesn't matter what pril you have, that's gonna be an ACE inhibitor.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9; PCOL-RAAS_26s.pdf slides 9–12; transcript 10/8", "note": "The drug list adds a “bonus 1” (angiotensin I → angiotensin 1-7 → AT2) and says most ACE inhibitors are prodrugs. Angiotensin 1-7 was not taught on 10/8; he named captopril and lisinopril as the active ones and said only the mechanism of action is needed. Neither is asked."},
{"id": "DL2-083", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei-cough", "tags": ["drug-list", "apply"], "source": "both", "stem": "Why do angiotensin-converting enzyme (ACE) inhibitors such as enalapril cause a dry cough?", "options": [{"t": "ACE no longer breaks down bradykinin", "correct": true, "why": "Bradykinin accumulates when ACE is blocked; the dry cough is its most common adverse effect."}, {"t": "Angiotensin II activates AT1 in the airway", "correct": false, "why": "ACE inhibitors lower angiotensin II, so AT1 activation falls; the cough comes from bradykinin."}, {"t": "Aldosterone rises and retains sodium", "correct": false, "why": "ACE inhibitors lower aldosterone (less angiotensin II on AT1), and aldosterone has no part in the cough."}, {"t": "β2 receptors in the lungs are blocked", "correct": false, "why": "ACE inhibitors act on an enzyme, not on β2 receptors; the cough comes from bradykinin."}], "teach": "Dry cough is the most common adverse effect of angiotensin-converting enzyme (ACE) inhibitors: 5 to 20% of patients, usually between 1 week and 6 months, from accumulation of bradykinin, which ACE normally breaks down. Most patients get past it; those who cannot tolerate it can switch to another class, such as an angiotensin II receptor blocker.", "quote": "Do you know what is the most common side effect associated with ACE inhibitors? That dry cough. … And then if you can't tolerate that, then you can go to a different class, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9; PCOL-RAAS_26s.pdf slides 12, 19; transcript 10/8"},
{"id": "DL2-084", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "arb", "tags": ["drug-list"], "source": "both", "stem": "Which of the following describes the mechanism of action of losartan?", "options": [{"t": "Reversible angiotensin II (AT1) receptor blocker", "correct": true, "why": "Any “-sartan” is an ARB (angiotensin II receptor blocker): a reversible, selective AT1 antagonist."}, {"t": "Reversible angiotensin-converting enzyme inhibitor", "correct": false, "why": "That is the “-prils” (captopril, lisinopril and others)."}, {"t": "Selective renin inhibitor", "correct": false, "why": "That is aliskiren, which acts on the first, rate-limiting enzyme; losartan blocks AT1 at the end."}, {"t": "Mineralocorticoid receptor antagonist", "correct": false, "why": "That is spironolactone and eplerenone, which block aldosterone in the kidney; losartan blocks the angiotensin II receptor."}], "teach": "Losartan, valsartan, olmesartan, telmisartan and irbesartan are angiotensin II receptor blockers (ARBs): reversible, selective AT1 antagonists with about 10,000-fold higher affinity for AT1 than for AT2. Blocking AT1 lowers total peripheral resistance, Na+ and water retention and aldosterone; angiotensin II, which rises, then activates AT2, which opposes AT1. Losartan is active, and its metabolite EXP 3174 is active too.", "quote": "So as long as you know one, you know them all, and those drugs are directly binding and inhibiting the AT1 receptor and thus preventing the binding of angiotensin 2.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9; PCOL-RAAS_26s.pdf slides 4, 13–14; transcript 10/8", "dupOf": "PE2-072"},
{"id": "DL2-085", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "acei-vs-arb", "tags": ["drug-list", "tell", "list"], "source": "both", "multi": true, "stem": "Which adverse reactions are more common with ACE (angiotensin-converting enzyme) inhibitors than with angiotensin II receptor blockers (ARBs)? Select all that apply.", "options": [{"t": "Dry cough", "correct": true, "why": "From accumulation of bradykinin; more with ACE inhibitors than with ARBs or renin inhibitors."}, {"t": "Angioedema", "correct": true, "why": "Also a bradykinin effect of ACE inhibitors; a patient with angioedema on an ACE inhibitor can try an ARB."}, {"t": "Hyperkalemia", "correct": false, "why": "Shared by the renin inhibitor, the ACE inhibitors and the ARBs."}, {"t": "First-dose hypotension", "correct": false, "why": "Shared by the renin inhibitor, ACE inhibitors and ARBs, which all lower angiotensin II action; not specific to ACE inhibitors."}, {"t": "Fetopathic potential", "correct": false, "why": "Shared by all three classes that act on the cascade; not specific to ACE inhibitors."}], "teach": "Only ACE inhibitors raise bradykinin, and two adverse reactions follow from it: dry cough and angioedema (swelling of the lips, face and airway). Hyperkalemia, first-dose hypotension and fetopathic potential are shared by the renin inhibitor, the ACE inhibitors and the ARBs.", "quote": "Now with the ACE inhibitors we have two side effects that seem to be more common associated with it because of the bradykinin. One is the dry cough that is more with the ACEs than you would get with the ARBs or the RAI inhibitors, and the other one is angioedema.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9; PCOL-RAAS_26s.pdf slide 19; transcript 10/8", "note": "The drug list gives angioedema for the ARBs (and aliskiren) and only dry cough as ACE-specific. Slide 19 puts both dry cough and angioedema under ACE inhibitors, and on 10/8 he called both more common with ACE inhibitors because of bradykinin. Keyed to the slide and lecture.", "dupOf": "L12-049"},
{"id": "DL2-086", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "spironolactone", "tags": ["drug-list"], "source": "both", "stem": "Which statement about spironolactone and eplerenone is CORRECT?", "options": [{"t": "They block the mineralocorticoid receptor", "correct": true, "why": "They are mineralocorticoid receptor (aldosterone) antagonists and potassium-sparing diuretics, acting at the late distal tubule and collecting duct."}, {"t": "They inhibit renin in the blood stream", "correct": false, "why": "That is aliskiren; spironolactone and eplerenone act at the end, on the aldosterone receptor in the kidney."}, {"t": "They block AT1 receptors in the blood stream", "correct": false, "why": "That is the angiotensin II receptor blockers; spironolactone blocks the receptor aldosterone uses."}, {"t": "They cause hypokalemia", "correct": false, "why": "They spare potassium; hyperkalemia is the expected reaction."}], "teach": "Spironolactone and eplerenone are mineralocorticoid receptor (MR) antagonists, also called aldosterone antagonists or potassium-sparing diuretics. Aldosterone acts on this nuclear receptor to make more Na+ channels, K+ channels and Na+/K+-ATPase pumps; blocking it means Na+ is lost and K+ is kept. Reactions: hyperkalemia, gastrointestinal effects (diarrhea), drowsiness, and with spironolactone (not eplerenone, the more kidney-selective MR blocker) gynecomastia and impotence in men.", "quote": "And then we have over here spironolactone, which is our aldosterone antagonist, also known as MR antagonist or potassium sparing diuretics.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 9–10; PCOL-RAAS_26s.pdf slides 20–22; transcript 10/8"},
{"id": "DL2-087", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "group-hyperkalemia", "tags": ["drug-list", "list"], "source": "both", "multi": true, "stem": "Which of the following may cause hyperkalemia? Select all that apply.", "options": [{"t": "Ramipril", "correct": true, "why": "An angiotensin-converting enzyme (ACE) inhibitor: hyperkalemia, more so with renal dysfunction."}, {"t": "Valsartan", "correct": true, "why": "An angiotensin II receptor blocker (ARB): hyperkalemia."}, {"t": "Eplerenone", "correct": true, "why": "A mineralocorticoid receptor antagonist (potassium-sparing diuretic): hyperkalemia."}, {"t": "Aliskiren", "correct": true, "why": "The renin inhibitor can also cause hyperkalemia, like the ACE inhibitors and ARBs."}, {"t": "Excess aldosterone", "correct": false, "why": "Aldosterone is the potassium-wasting hormone: more aldosterone means more K+ loss."}], "teach": "The potassium-sparing diuretics (spironolactone, eplerenone) cause hyperkalemia, and so can the angiotensin-converting enzyme (ACE) inhibitors, the angiotensin II receptor blockers (ARBs) and the renin inhibitor aliskiren, more so with renal dysfunction. Aldosterone does the opposite: it retains Na+ at the cost of K+.", "quote": "But remember that both the ACEs, the ARBs, and the RAIN inhibitors can also cause hyperkalemia. That can be even more predominant if you have renal dysfunction.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 8–10; PCOL-RAAS_26s.pdf slides 19–22; transcript 10/8", "note": "The drug list does not give hyperkalemia for aliskiren; slide 19 (“Adverse Effects (Ri, ACEi & ARBs)”) and his 10/8 hyperkalemia poll (key: all of the above) include it. Keyed to the slide and lecture. Metoprolol, the distractor in the list-only version, was replaced: hyperkalemia was not discussed for it.", "dupOf": "PE2-056", "level": 1},
{"id": "DL2-088", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "raas", "skill": "drug", "concept": "metoprolol-renin", "tags": ["drug-list", "apply"], "source": "both", "stem": "How does metoprolol lower renin–angiotensin–aldosterone system (RAAS) activity?", "options": [{"t": "It blocks renal β1, so less renin is made", "correct": true, "why": "A selective β1 blocker: on the juxtaglomerular cells this suppresses renin production."}, {"t": "It inhibits angiotensin-converting enzyme", "correct": false, "why": "That is the “-prils”; metoprolol acts upstream, on renin release."}, {"t": "It blocks the mineralocorticoid receptor", "correct": false, "why": "That is spironolactone and eplerenone; metoprolol acts on β1 in the kidney, upstream of aldosterone."}, {"t": "It inhibits renin directly in the blood stream", "correct": false, "why": "Direct renin inhibition is aliskiren; metoprolol lowers renin release through β1 and does not inhibit renin itself."}, {"t": "It abolishes renin release", "correct": false, "why": "The macula densa (sodium) and baroreceptor controls remain, so renin is suppressed, not abolished."}], "teach": "Metoprolol is a selective β1 antagonist; all β blockers block β1 and so can lower renin production. Blocking β1 on the juxtaglomerular cells suppresses renin, but the macula densa and intrarenal baroreceptor controls remain, so renin is not abolished. Less renin means less angiotensin I, angiotensin II and aldosterone.", "quote": "And by blocking the beta ones in the kidney, you're also gonna decrease renin production, right? You're not gonna abolish because you you have the sodium component and the, the barrel receptor component, but you can suppress it.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 10; PCOL-RAAS_26s.pdf slides 7, 24–25; transcript 10/8", "note": "The drug list says “Less renin production → no RAAS pathway”; on 10/8 he said renin is suppressed, not abolished. Keyed to the lecture.", "level": 1}
);
